{{"language":"Solidity","sources":{"contracts/core/CLFactory.sol":{"content":"// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity =0.7.6;
pragma abicoder v2;

import '../gauge/interfaces/ILeafVoter.sol';
import './CLPool.sol';
import './indexation/CLFactoryIndexation.sol';
import './interfaces/ICLFactory.sol';
import './interfaces/IFactoryRegistry.sol';
import './interfaces/fees/IFeeModule.sol';
import '@openzeppelin/contracts/proxy/Clones.sol';

/// @title Canonical CL factory
/// @notice Deploys CL pools and manages ownership and control over pool protocol fees
contract CLFactory is CLFactoryIndexation, ICLFactory {
  /// @inheritdoc ICLFactory
  ILeafVoter public override voter;
  /// @inheritdoc ICLFactory
  address public immutable override poolImplementation;
  /// @inheritdoc ICLFactory
  address public immutable override positionManager;
  /// @inheritdoc ICLFactory
  IFactoryRegistry public immutable override factoryRegistry;
  /// @inheritdoc ICLFactory
  address public override owner;
  /// @inheritdoc ICLFactory
  address public override swapFeeManager;
  /// @inheritdoc ICLFactory
  address public override unstakedFeeManager;
  /// @inheritdoc ICLFactory
  address public override unstakedFeeModule;
  /// @inheritdoc ICLFactory
  address public override defaultSwapHook;
  /// @inheritdoc ICLFactory
  mapping(address => address) public override poolSwapHook;
  /// @inheritdoc ICLFactory
  uint24 public override defaultUnstakedFee;
  /// @inheritdoc ICLFactory
  address public override discountRegistryManager;
  /// @inheritdoc ICLFactory
  address public override discountRegistry;
  /// @inheritdoc ICLFactory
  address public override clPoolTape;
  /// @inheritdoc ICLFactory
  address public override clPoolTapeManager;

  /// @inheritdoc ICLFactory
  mapping(int24 => uint24) public override tickSpacingToFee;
  /// @dev Used in VotingEscrow to determine if a contract is a valid pool
  mapping(address => bool) private _isPool;
  /// @inheritdoc ICLFactory
  address[] public override allPools;

  int24[] private _tickSpacings;
  mapping(address => mapping(address => mapping(int24 => address))) internal _getPool;

  constructor(ConstructorParams memory _params) {
    require(_params.owner != address(0), 'OwnerIsZero');
    require(_params.swapFeeManager != address(0), 'SwapFeeManagerIsZero');
    require(_params.unstakedFeeManager != address(0), 'UnstakedFeeManagerIsZero');
    require(_params.poolImplementation != address(0), 'PoolImplementationIsZero');
    require(_params.positionManager != address(0), 'PositionManagerIsZero');
    require(_params.factoryRegistry != address(0), 'FactoryRegistryIsZero');
    require(_params.discountRegistryManager != address(0), 'DiscountRegistryManagerIsZero');
    require(_params.clPoolTapeManager != address(0), 'ClPoolTapeManagerIsZero');
    owner = _params.owner;
    swapFeeManager = _params.swapFeeManager;
    unstakedFeeManager = _params.unstakedFeeManager;
    voter = ILeafVoter(_params.voter);
    poolImplementation = _params.poolImplementation;
    positionManager = _params.positionManager;
    factoryRegistry = IFactoryRegistry(_params.factoryRegistry);
    defaultSwapHook = _params.defaultSwapHook;
    discountRegistryManager = _params.discountRegistryManager;
    clPoolTapeManager = _params.clPoolTapeManager;
    defaultUnstakedFee = 0;
    emit OwnerChanged(address(0), _params.owner);
    emit SwapFeeManagerChanged(address(0), _params.swapFeeManager);
    emit UnstakedFeeManagerChanged(address(0), _params.unstakedFeeManager);
    emit DefaultUnstakedFeeChanged(0, 0);
    emit DefaultSwapHookChanged(_params.defaultSwapHook);
    emit DiscountRegistryManagerChanged(_params.discountRegistryManager);
    emit ClPoolTapeManagerChanged(_params.clPoolTapeManager);

    for (uint256 i; i < _params.initialFeeTiers.length; ++i) {
      enableTickSpacing(_params.initialFeeTiers[i].tickSpacing, _params.initialFeeTiers[i].fee);
    }
  }

  /// @inheritdoc ICLFactory
  function createPool(address tokenA, address tokenB, uint24 tickSpacing) external override returns (address) {
    return createPool({
      tokenA: tokenA,
      tokenB: tokenB,
      tickSpacing: int24(tickSpacing),
      sqrtPriceX96: 79_228_162_514_264_337_593_543_950_336 // encodePriceSqrt(1, 1)
    });
  }

  /// @inheritdoc ICLFactory
  function createPool(
    address tokenA,
    address tokenB,
    int24 tickSpacing,
    uint160 sqrtPriceX96
  ) public override returns (address pool) {
    require(tokenA != tokenB);
    (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
    require(token0 != address(0));
    require(tickSpacingToFee[tickSpacing] != 0);
    require(_getPool[token0][token1][tickSpacing] == address(0));
    pool =
      Clones.cloneDeterministic({master: poolImplementation, salt: keccak256(abi.encode(token0, token1, tickSpacing))});
    CLPool(pool).initialize({
      _factory: address(this),
      _token0: token0,
      _token1: token1,
      _tickSpacing: tickSpacing,
      _factoryRegistry: address(factoryRegistry),
      _sqrtPriceX96: sqrtPriceX96
    });
    allPools.push(pool);
    _isPool[pool] = true;
    _getPool[token0][token1][tickSpacing] = pool;
    // populate mapping in the reverse direction, deliberate choice to avoid the cost of comparing addresses
    _getPool[token1][token0][tickSpacing] = pool;

    /// @dev This function is invoked only after the pool is deployed
    ///      and only after all validations are passed.
    _createPoolHook({_tokenA: tokenA, _tokenB: tokenB, _pool: pool});

    /// @dev Records the pool as a target so gauges can be created for it. Reverts until
    ///      this factory is approved as a target factory in the registry.
    factoryRegistry.registerTarget(pool);

    emit PoolCreated(token0, token1, tickSpacing, pool);
  }

  /// @inheritdoc ICLFactory
  function setOwner(address _owner) external override {
    address cachedOwner = owner;
    require(msg.sender == cachedOwner);
    require(_owner != address(0));
    emit OwnerChanged(cachedOwner, _owner);
    owner = _owner;
  }

  /// @inheritdoc ICLFactory
  function setVoter(address _voter) external override {
    require(msg.sender == owner, 'NotOwner');
    require(address(voter) == address(0), 'VoterAlreadySet');
    require(_voter != address(0), 'VoterIsZero');
    voter = ILeafVoter(_voter);
    emit VoterSet(_voter);
  }

  /// @inheritdoc ICLFactory
  function setSwapFeeManager(address _swapFeeManager) external override {
    address cachedSwapFeeManager = swapFeeManager;
    require(msg.sender == cachedSwapFeeManager);
    require(_swapFeeManager != address(0));
    swapFeeManager = _swapFeeManager;
    emit SwapFeeManagerChanged(cachedSwapFeeManager, _swapFeeManager);
  }

  /// @inheritdoc ICLFactory
  function setUnstakedFeeManager(address _unstakedFeeManager) external override {
    address cachedUnstakedFeeManager = unstakedFeeManager;
    require(msg.sender == cachedUnstakedFeeManager);
    require(_unstakedFeeManager != address(0));
    unstakedFeeManager = _unstakedFeeManager;
    emit UnstakedFeeManagerChanged(cachedUnstakedFeeManager, _unstakedFeeManager);
  }

  /// @inheritdoc ICLFactory
  function setDiscountRegistryManager(address _discountRegistryManager) external override {
    require(msg.sender == discountRegistryManager, 'NotDiscountRegistryManager');
    require(_discountRegistryManager != address(0), 'DiscountRegistryManagerIsZero');

    discountRegistryManager = _discountRegistryManager;
    emit DiscountRegistryManagerChanged(_discountRegistryManager);
  }

  /// @inheritdoc ICLFactory
  function setUnstakedFeeModule(address _unstakedFeeModule) external override {
    require(msg.sender == unstakedFeeManager);
    require(_unstakedFeeModule != address(0));
    address oldFeeModule = unstakedFeeModule;
    unstakedFeeModule = _unstakedFeeModule;
    emit UnstakedFeeModuleChanged(oldFeeModule, _unstakedFeeModule);
  }

  /// @inheritdoc ICLFactory
  function setDefaultUnstakedFee(uint24 _defaultUnstakedFee) external override {
    require(msg.sender == unstakedFeeManager);
    require(_defaultUnstakedFee <= 500_000);
    uint24 oldUnstakedFee = defaultUnstakedFee;
    defaultUnstakedFee = _defaultUnstakedFee;
    emit DefaultUnstakedFeeChanged(oldUnstakedFee, _defaultUnstakedFee);
  }

  /// @inheritdoc ICLFactory
  function setDefaultSwapHook(address _swapHook) external override {
    require(msg.sender == swapFeeManager, 'NotSwapFeeManager');
    defaultSwapHook = _swapHook;

    emit DefaultSwapHookChanged(_swapHook);
  }

  /// @inheritdoc ICLFactory
  function getPoolSwapHook(address _pool) external view override returns (address) {
    address poolHook = poolSwapHook[_pool];
    return poolHook == address(0) ? defaultSwapHook : poolHook;
  }

  /// @inheritdoc ICLFactory
  function setPoolSwapHook(address[] calldata _pools, address[] calldata _swapHooks) external override {
    require(msg.sender == swapFeeManager, 'NotSwapFeeManager');
    uint256 poolsLength = _pools.length;
    require(poolsLength == _swapHooks.length, 'LMM');

    address pool;
    address hook;
    for (uint256 i = 0; i < poolsLength; i++) {
      pool = _pools[i];
      hook = _swapHooks[i];
      poolSwapHook[pool] = hook;
      emit PoolSwapHookChanged(pool, hook);
    }
  }

  /// @inheritdoc ICLFactory
  function setDiscountRegistry(address _discountRegistry) external override {
    require(msg.sender == discountRegistryManager, 'NotDiscountRegistryManager');
    require(_discountRegistry != address(0), 'DiscountRegistryIsZero');

    discountRegistry = _discountRegistry;

    emit DiscountRegistryChanged(_discountRegistry);
  }

  /// @inheritdoc ICLFactory
  function setClPoolTapeManager(address _clPoolTapeManager) external override {
    require(msg.sender == clPoolTapeManager, 'NotClPoolTapeManager');
    require(_clPoolTapeManager != address(0), 'ClPoolTapeManagerIsZero');
    clPoolTapeManager = _clPoolTapeManager;
    emit ClPoolTapeManagerChanged(_clPoolTapeManager);
  }

  /// @inheritdoc ICLFactory
  function setClPoolTape(address _clPoolTape) external override {
    require(msg.sender == clPoolTapeManager, 'NotClPoolTapeManager');
    clPoolTape = _clPoolTape;
    emit ClPoolTapeChanged(_clPoolTape);
  }

  /// @inheritdoc ICLFactory
  function getUnstakedFee(address pool) external view override returns (uint24) {
    ILeafVoter _leafVoter = voter;
    if (address(_leafVoter) == address(0)) {
      return 0;
    }
    address gauge = factoryRegistry.targetToGauge(pool);
    // a zero emission cap disables fee collection on the gauge, so stop charging the fee
    if (gauge == address(0) || !_leafVoter.isActivated(gauge) || factoryRegistry.emissionCap(gauge) == 0) {
      return 0;
    }

    if (unstakedFeeModule != address(0)) {
      try IFeeModule(unstakedFeeModule).getFee(pool) returns (uint24 fee) {
        if (fee <= 1_000_000) return fee;
      } catch {}
    }
    return defaultUnstakedFee;
  }

  /// @inheritdoc ICLFactory
  function enableTickSpacing(int24 tickSpacing, uint24 fee) public override {
    require(msg.sender == owner);
    require(fee > 0 && fee <= 100_000);
    // tick spacing is capped at 16384 to prevent the situation where tickSpacing is so large that
    // TickBitmap#nextInitializedTickWithinOneWord overflows int24 container from a valid tick
    // 16384 ticks represents a >5x price change with ticks of 1 bips
    require(tickSpacing > 0 && tickSpacing < 16_384);
    require(tickSpacingToFee[tickSpacing] == 0);

    tickSpacingToFee[tickSpacing] = fee;
    _tickSpacings.push(tickSpacing);
    emit TickSpacingEnabled(tickSpacing, fee);
  }

  function getPool(address tokenA, address tokenB, int24 tickSpacing) external view override returns (address) {
    return _getPool[tokenA][tokenB][tickSpacing];
  }

  function getPool(address tokenA, address tokenB, uint24 tickSpacing) external view override returns (address) {
    return _getPool[tokenA][tokenB][int24(tickSpacing)];
  }

  /// @inheritdoc ICLFactory
  function tickSpacings() external view override returns (int24[] memory) {
    return _tickSpacings;
  }

  /// @inheritdoc ICLFactory
  function allPoolsLength() external view override returns (uint256) {
    return allPools.length;
  }

  /// @inheritdoc ICLFactory
  function isPool(address pool) external view override returns (bool) {
    return _isPool[pool];
  }
}
"},"contracts/gauge/interfaces/IGauge.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity =0.7.6;

interface IGauge {
  /**
   * @notice Emitted when the gauge collects pool fees through the VotingRewardsManager.
   * @param _caller The address that triggered fee collection.
   * @param _claimed0 The amount of token0 fees collected.
   * @param _claimed1 The amount of token1 fees collected.
   */
  event ClaimFees(address indexed _caller, uint256 _claimed0, uint256 _claimed1);

  /**
   * @notice Emitted when an account grants or revokes claim approval for an operator
   * @param _account The account whose approval state changed
   * @param _operator The operator being approved or revoked
   * @param _approved The new approval state
   */
  event ClaimApproval(address indexed _account, address indexed _operator, bool _approved);

  /**
   * @notice Emitted when an owner grants or revokes blanket withdrawal approval for an operator
   * @param _owner The owner whose approval changed
   * @param _operator The operator being approved or revoked
   * @param _approved The new approval state
   */
  event ApprovalForAll(address indexed _owner, address indexed _operator, bool _approved);

  /**
   * @notice Emitted when a referral's deferred emissions are claimed.
   * @param _referral The referral address whose deferred emissions were claimed.
   * @param _recipient The recipient of the claimed emissions.
   * @param _amount The deferred referral emissions paid to the recipient.
   */
  event ReferralEmissionsClaimed(address indexed _referral, address indexed _recipient, uint256 _amount);

  /**
   * @notice Deposit a staked position
   * @param _lp A token amount for V2 gauges or an NFT token ID for CL gauges
   */
  function deposit(uint256 _lp) external;

  /**
   * @notice Deposit a staked position on behalf of an owner
   * @dev For V2 gauges, approved MetaRouters are trusted to restrict `_owner` to the account that authorized the
   *      routed deposit; otherwise, they could reset another account's early-unstake penalty timer.
   * @param _lp A token amount for V2 gauges or an NFT token ID for CL gauges
   * @param _owner The address credited as the staked owner
   */
  function depositFor(uint256 _lp, address _owner) external;

  /**
   * @notice Withdraw a staked position owned by the caller
   * @param _lp A token amount for V2 gauges or an NFT token ID for CL gauges
   */
  function withdraw(uint256 _lp) external;

  /**
   * @notice Withdraw a staked position on behalf of an account
   * @param _lp A token amount for V2 gauges or an NFT token ID for CL gauges
   * @param _account The position owner
   */
  function withdrawFrom(uint256 _lp, address _account) external;

  /**
   * @notice Claim accrued emissions
   * @dev Requires the caller to be the LP or an operator with claim approval
   * @dev For CL gauges, the account-wide claim also includes account-level deferred LP emissions
   * @param _account The address of the LP staker whose emissions are being claimed
   * @param _recipient The recipient of the claimed emissions
   */
  function claimEmissions(address _account, address _recipient) external;

  /**
   * @notice Claims a referral's deferred emissions.
   * @dev Requires the caller to be the referral or an operator with claim approval.
   * @dev Contract referrals must be able to call this function or approve an operator to call it on their behalf.
   * @param _referral The referral address whose deferred emissions are being claimed.
   * @param _recipient The recipient of the claimed emissions.
   */
  function claimReferralEmissions(address _referral, address _recipient) external;

  /**
   * @notice Grant or revoke an operator's approval to claim emissions on behalf of the caller
   * @param _operator The operator to approve or revoke
   * @param _approved True to approve, false to revoke
   */
  function approveForClaim(address _operator, bool _approved) external;

  /**
   * @notice Grant or revoke blanket withdrawal authorization for an operator over all staked positions
   * @param _operator The operator to authorize or revoke
   * @param _approved True to grant blanket approval, false to revoke
   */
  function setApprovalForAll(address _operator, bool _approved) external;

  /**
   * @notice Approve an operator to withdraw a staked position
   * @param _operator The operator to authorize
   * @param _lp A token amount for V2 gauges or an NFT token ID for CL gauges
   */
  function approve(address _operator, uint256 _lp) external;

  /**
   * @notice Collect currently claimable pool fees directly to the VotingRewardsManager.
   * @dev Only callable by the VotingRewardsManager.
   * @return _amount0 The token0 fees collected.
   * @return _amount1 The token1 fees collected.
   */
  function collectFees() external returns (uint256 _amount0, uint256 _amount1);

  /**
   * @notice LeafVoter contract used for gauge settlement.
   * @return The address of the LeafVoter.
   */
  function voter() external view returns (address);

  /**
   * @notice Address of the factory that created this gauge.
   * @return The address of the gauge factory.
   */
  function gaugeFactory() external view returns (address);

  /**
   * @notice Address of the VotingRewardsManager contract linked to the gauge.
   * @return The address of the VotingRewardsManager.
   */
  function votingRewardsManager() external view returns (address);

  /**
   * @notice Returns if gauge is linked to a legitimate pool.
   * @return Whether the gauge is linked to a legitimate pool.
   */
  function isPool() external view returns (bool);

  /**
   * @notice The gauge's cursor into the LeafVoter's cumulative reward share accumulator
   * @return The cumulative reward share at the gauge's last settlement
   */
  function lastCumulativeRewardShare() external view returns (uint256);

  /**
   * @notice Estimates the claimable emissions for a given account
   * @dev Rewards accrued since the last settlement are an estimate
   * @dev For CL gauges, includes the account's net deferred LP emissions
   * @param _account The address of the LP staker
   * @return The estimated claimable amount
   */
  function earned(address _account) external view returns (uint256);

  /**
   * @notice Whether an operator is approved to claim emissions on behalf of an account
   * @param _account The account that granted the approval
   * @param _operator The operator being queried
   * @return True if the operator is approved
   */
  function approvedForClaim(address _account, address _operator) external view returns (bool);

  /**
   * @notice Returns deferred emissions stored for a referral address
   * @param _referral The referral address credited with the emissions
   * @return The deferred referral emissions
   */
  function deferredReferralEmissions(address _referral) external view returns (uint256);

  /**
   * @notice Returns whether an operator has blanket withdrawal authorization for an owner's positions
   * @param _owner The staked position owner
   * @param _operator The candidate operator
   * @return True if blanket approval is active
   */
  function isApprovedForAll(address _owner, address _operator) external view returns (bool);

  /**
   * @notice Return currently claimable pool fees without moving tokens or mutating state.
   * @return _amount0 The currently pending token0 fees.
   * @return _amount1 The currently pending token1 fees.
   */
  function pendingFees() external view returns (uint256 _amount0, uint256 _amount1);
}
"},"contracts/core/interfaces/callback/ICLFlashCallback.sol":{"content":"// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title Callback for ICLPoolActions#flash
/// @notice Any contract that calls ICLPoolActions#flash must implement this interface
interface ICLFlashCallback {
  /// @notice Called to `msg.sender` after transferring to the recipient from ICLPool#flash.
  /// @dev In the implementation you must repay the pool the tokens sent by flash plus the computed fee amounts.
  /// The caller of this method must be checked to be a CLPool deployed by the canonical CLFactory.
  /// @param fee0 The fee amount in token0 due to the pool by the end of the flash
  /// @param fee1 The fee amount in token1 due to the pool by the end of the flash
  /// @param data Any data passed through by the caller via the ICLPoolActions#flash call
  function uniswapV3FlashCallback(uint256 fee0, uint256 fee1, bytes calldata data) external;
}
"},"contracts/core/libraries/SafeCast.sol":{"content":"// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title Safe casting methods
/// @notice Contains methods for safely casting between types
library SafeCast {
  /// @notice Cast a uint256 to a uint160, revert on overflow
  /// @param y The uint256 to be downcasted
  /// @return z The downcasted integer, now type uint160
  function toUint160(uint256 y) internal pure returns (uint160 z) {
    require((z = uint160(y)) == y);
  }

  /// @notice Cast a int256 to a int128, revert on overflow or underflow
  /// @param y The int256 to be downcasted
  /// @return z The downcasted integer, now type int128
  function toInt128(int256 y) internal pure returns (int128 z) {
    require((z = int128(y)) == y);
  }

  /// @notice Cast a uint256 to a int256, revert on overflow
  /// @param y The uint256 to be casted
  /// @return z The casted integer, now type int256
  function toInt256(uint256 y) internal pure returns (int256 z) {
    require(y < 2 ** 255);
    z = int256(y);
  }
}
"},"contracts/core/libraries/CLPoolNonSwapPath.sol":{"content":"// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity =0.7.6;
pragma abicoder v2;

import {FixedPoint128} from './FixedPoint128.sol';
import {FullMath} from './FullMath.sol';
import {LiquidityMath} from './LiquidityMath.sol';
import {LowGasSafeMath} from './LowGasSafeMath.sol';
import {Oracle} from './Oracle.sol';
import {Position} from './Position.sol';
import {SafeCast} from './SafeCast.sol';
import {SqrtPriceMath} from './SqrtPriceMath.sol';
import {Tick} from './Tick.sol';
import {TickBitmap} from './TickBitmap.sol';
import {TickMath} from './TickMath.sol';
import {TransferHelper} from './TransferHelper.sol';
import {SwapHookLib} from './hook/SwapHookLib.sol';

import {ICLFactory} from '../interfaces/ICLFactory.sol';
import {IERC20Minimal} from '../interfaces/IERC20Minimal.sol';
import {IFactoryRegistry} from '../interfaces/IFactoryRegistry.sol';
import {ICLFlashCallback} from '../interfaces/callback/ICLFlashCallback.sol';
import {ICLMintCallback} from '../interfaces/callback/ICLMintCallback.sol';
import {ISwapHook} from '../interfaces/hook/ISwapHook.sol';

import {CLPool} from '../CLPool.sol';

/// @notice Externally linked implementations of non-swap CLPool paths.
/// @dev CLPool keeps its public entry points and delegates only the function bodies declared here.
library CLPoolNonSwapPath {
  using LowGasSafeMath for uint256;
  using SafeCast for int256;
  using Tick for mapping(int24 => Tick.Info);
  using TickBitmap for mapping(int16 => uint256);
  using Position for mapping(bytes32 => Position.Info);
  using Position for Position.Info;
  using Oracle for Oracle.Observation[65_535];
  using SwapHookLib for address;

  event Initialize(uint160 sqrtPriceX96, int24 tick);
  event IncreaseObservationCardinalityNext(uint16 observationCardinalityNextOld, uint16 observationCardinalityNextNew);
  event Flash(
    address indexed sender, address indexed recipient, uint256 amount0, uint256 amount1, uint256 paid0, uint256 paid1
  );
  event Mint(
    address sender,
    address indexed owner,
    int24 indexed tickLower,
    int24 indexed tickUpper,
    uint128 amount,
    uint256 amount0,
    uint256 amount1
  );
  event Burn(
    address indexed owner,
    int24 indexed tickLower,
    int24 indexed tickUpper,
    uint128 amount,
    uint256 amount0,
    uint256 amount1
  );
  event Collect(
    address indexed owner,
    address recipient,
    int24 indexed tickLower,
    int24 indexed tickUpper,
    uint128 amount0,
    uint128 amount1
  );
  event CollectFees(address indexed recipient, uint128 amount0, uint128 amount1);

  struct FlashInput {
    address token0;
    address token1;
    address factory;
    int24 tickSpacing;
    uint128 liquidity;
    uint128 stakedLiquidity;
    address recipient;
    uint256 amount0;
    uint256 amount1;
  }

  struct ModifyPositionInput {
    address owner;
    int24 tickLower;
    int24 tickUpper;
    uint128 liquidity;
    uint128 maxLiquidityPerTick;
    uint256 feeGrowthGlobal0X128;
    uint256 feeGrowthGlobal1X128;
    uint256 rewardGrowthGlobalX128;
    address gauge;
    int24 tickSpacing;
    uint128 amount;
  }

  struct PositionObservation {
    int56 tickCumulative;
    uint160 secondsPerLiquidityCumulativeX128;
    int24 currentTick;
    int128 liquidityDelta;
  }

  struct StakeInput {
    address nft;
    int24 tickLower;
    int24 tickUpper;
    int24 tick;
    int128 stakedLiquidityDelta;
    uint256 feeGrowthGlobal0X128;
    uint256 feeGrowthGlobal1X128;
  }

  struct SnapshotInput {
    int24 tickLower;
    int24 tickUpper;
    int24 tick;
    uint16 observationIndex;
    uint16 observationCardinality;
    uint128 liquidity;
  }

  function initializeSlot0(
    CLPool.Slot0 storage slot0,
    Oracle.Observation[65_535] storage observations,
    uint160 sqrtPriceX96,
    int24 tick,
    int24 tickSpacing
  ) external returns (uint128 maxLiquidityPerTick) {
    (uint16 cardinality, uint16 cardinalityNext) = observations.initialize(uint32(block.timestamp));

    slot0.sqrtPriceX96 = sqrtPriceX96;
    slot0.tick = tick;
    slot0.observationIndex = 0;
    slot0.observationCardinality = cardinality;
    slot0.observationCardinalityNext = cardinalityNext;
    slot0.unlocked = true;

    emit Initialize(sqrtPriceX96, tick);
    return Tick.tickSpacingToMaxLiquidityPerTick(tickSpacing);
  }

  function flashFee(
    ISwapHook.FlashParams memory flashParams,
    address factory,
    int24 tickSpacing
  ) external view returns (uint24) {
    address pool = address(this);
    return ICLFactory(factory).getPoolSwapHook(pool).getFlashFee(pool, flashParams, factory, tickSpacing);
  }

  function beforeSwapFee(
    ISwapHook.SwapParams memory swapParams,
    address factory,
    int24 tickSpacing
  ) external view returns (uint24) {
    address pool = address(this);
    return ICLFactory(factory).getPoolSwapHook(pool).getBeforeSwapFee(pool, swapParams, factory, tickSpacing);
  }

  function afterSwapFee(
    ISwapHook.SwapParams memory swapParams,
    ISwapHook.AfterSwapParams memory afterSwapParams,
    address factory
  ) external view returns (uint24) {
    address pool = address(this);
    return ICLFactory(factory).getPoolSwapHook(pool).getAfterSwapFee(pool, swapParams, afterSwapParams);
  }

  function stakePositions(
    mapping(bytes32 => Position.Info) storage positions,
    mapping(int24 => Tick.Info) storage ticks,
    address nft,
    int24 tickLower,
    int24 tickUpper,
    int24 tick,
    int128 stakedLiquidityDelta,
    uint256 feeGrowthGlobal0X128,
    uint256 feeGrowthGlobal1X128
  ) external {
    _stakePositions(
      positions,
      ticks,
      StakeInput({
        nft: nft,
        tickLower: tickLower,
        tickUpper: tickUpper,
        tick: tick,
        stakedLiquidityDelta: stakedLiquidityDelta,
        feeGrowthGlobal0X128: feeGrowthGlobal0X128,
        feeGrowthGlobal1X128: feeGrowthGlobal1X128
      })
    );
  }

  function _stakePositions(
    mapping(bytes32 => Position.Info) storage positions,
    mapping(int24 => Tick.Info) storage ticks,
    StakeInput memory input
  ) private {
    Position.Info storage nftPosition = positions.get(input.nft, input.tickLower, input.tickUpper);
    Position.Info storage gaugePosition = positions.get(msg.sender, input.tickLower, input.tickUpper);
    (uint256 feeGrowthInside0X128, uint256 feeGrowthInside1X128) = ticks.getFeeGrowthInside(
      input.tickLower, input.tickUpper, input.tick, input.feeGrowthGlobal0X128, input.feeGrowthGlobal1X128
    );
    nftPosition.update(-input.stakedLiquidityDelta, feeGrowthInside0X128, feeGrowthInside1X128, false);
    gaugePosition.update(input.stakedLiquidityDelta, feeGrowthInside0X128, feeGrowthInside1X128, true);
    if (ticks[input.tickLower].initialized) ticks.updateStake(input.tickLower, input.stakedLiquidityDelta, false);
    if (ticks[input.tickUpper].initialized) ticks.updateStake(input.tickUpper, input.stakedLiquidityDelta, true);
  }

  function snapshotCumulativesInside(
    mapping(int24 => Tick.Info) storage ticks,
    Oracle.Observation[65_535] storage observations,
    int24 tickLower,
    int24 tickUpper,
    int24 tick,
    uint16 observationIndex,
    uint16 observationCardinality,
    uint128 liquidity
  ) external view returns (int56 tickCumulativeInside, uint160 secondsPerLiquidityInsideX128, uint32 secondsInside) {
    return _snapshotCumulativesInside(
      ticks,
      observations,
      SnapshotInput({
        tickLower: tickLower,
        tickUpper: tickUpper,
        tick: tick,
        observationIndex: observationIndex,
        observationCardinality: observationCardinality,
        liquidity: liquidity
      })
    );
  }

  function _snapshotCumulativesInside(
    mapping(int24 => Tick.Info) storage ticks,
    Oracle.Observation[65_535] storage observations,
    SnapshotInput memory input
  ) private view returns (int56 tickCumulativeInside, uint160 secondsPerLiquidityInsideX128, uint32 secondsInside) {
    _checkTicks(input.tickLower, input.tickUpper);
    Tick.Info storage lower = ticks[input.tickLower];
    Tick.Info storage upper = ticks[input.tickUpper];
    require(lower.initialized);
    require(upper.initialized);

    if (input.tick < input.tickLower) {
      return (
        lower.tickCumulativeOutside - upper.tickCumulativeOutside,
        lower.secondsPerLiquidityOutsideX128 - upper.secondsPerLiquidityOutsideX128,
        lower.secondsOutside - upper.secondsOutside
      );
    }
    if (input.tick >= input.tickUpper) {
      return (
        upper.tickCumulativeOutside - lower.tickCumulativeOutside,
        upper.secondsPerLiquidityOutsideX128 - lower.secondsPerLiquidityOutsideX128,
        upper.secondsOutside - lower.secondsOutside
      );
    }
    (int56 tickCumulative, uint160 secondsPerLiquidityCumulativeX128) = observations.observeSingle(
      uint32(block.timestamp), 0, input.tick, input.observationIndex, input.liquidity, input.observationCardinality
    );
    return (
      tickCumulative - lower.tickCumulativeOutside - upper.tickCumulativeOutside,
      secondsPerLiquidityCumulativeX128 - lower.secondsPerLiquidityOutsideX128 - upper.secondsPerLiquidityOutsideX128,
      uint32(block.timestamp) - lower.secondsOutside - upper.secondsOutside
    );
  }

  function getFeeGrowthInside(
    mapping(int24 => Tick.Info) storage ticks,
    int24 tickLower,
    int24 tickUpper,
    int24 tickCurrent,
    uint256 feeGrowthGlobal0X128,
    uint256 feeGrowthGlobal1X128
  ) external view returns (uint256 feeGrowthInside0X128, uint256 feeGrowthInside1X128) {
    _checkTicks(tickLower, tickUpper);
    return ticks.getFeeGrowthInside(tickLower, tickUpper, tickCurrent, feeGrowthGlobal0X128, feeGrowthGlobal1X128);
  }

  function getRewardGrowthInside(
    mapping(int24 => Tick.Info) storage ticks,
    int24 tickLower,
    int24 tickUpper,
    int24 tickCurrent,
    uint256 rewardGrowthGlobalX128,
    uint256 storedRewardGrowthGlobalX128
  ) external view returns (uint256 rewardGrowthInsideX128) {
    _checkTicks(tickLower, tickUpper);
    if (rewardGrowthGlobalX128 == 0) rewardGrowthGlobalX128 = storedRewardGrowthGlobalX128;
    return ticks.getRewardGrowthInside(tickLower, tickUpper, tickCurrent, rewardGrowthGlobalX128);
  }

  function increaseObservationCardinalityNext(
    Oracle.Observation[65_535] storage observations,
    CLPool.Slot0 storage slot0,
    uint16 observationCardinalityNext
  ) external {
    uint16 observationCardinalityNextOld = slot0.observationCardinalityNext;
    uint16 observationCardinalityNextNew = observations.grow(observationCardinalityNextOld, observationCardinalityNext);
    slot0.observationCardinalityNext = observationCardinalityNextNew;
    if (observationCardinalityNextOld != observationCardinalityNextNew) {
      emit IncreaseObservationCardinalityNext(observationCardinalityNextOld, observationCardinalityNextNew);
    }
  }

  function _checkTicks(int24 tickLower, int24 tickUpper) private pure {
    require(tickLower < tickUpper, 'TLU');
    require(tickLower >= TickMath.MIN_TICK, 'TLM');
    require(tickUpper <= TickMath.MAX_TICK, 'TUM');
  }

  function modifyPositionForMint(
    mapping(bytes32 => Position.Info) storage positions,
    mapping(int24 => Tick.Info) storage ticks,
    mapping(int16 => uint256) storage tickBitmap,
    Oracle.Observation[65_535] storage observations,
    CLPool.Slot0 storage slot0,
    ModifyPositionInput memory input
  ) external returns (uint128 liquidityAfter, uint256 amount0, uint256 amount1) {
    require(input.amount > 0);

    int256 amount0Int;
    int256 amount1Int;
    (liquidityAfter, amount0Int, amount1Int) =
      _modifyPosition(positions, ticks, tickBitmap, observations, slot0, input, int256(input.amount).toInt128());

    amount0 = uint256(amount0Int);
    amount1 = uint256(amount1Int);
  }

  function settleMint(
    ModifyPositionInput memory input,
    uint256 amount0,
    uint256 amount1,
    address token0,
    address token1,
    bytes calldata data
  ) external {
    uint256 balance0Before;
    uint256 balance1Before;
    if (amount0 > 0) balance0Before = _balance(token0);
    if (amount1 > 0) balance1Before = _balance(token1);
    ICLMintCallback(msg.sender).uniswapV3MintCallback(amount0, amount1, data);
    if (amount0 > 0) require(balance0Before.add(amount0) <= _balance(token0), 'M0');
    if (amount1 > 0) require(balance1Before.add(amount1) <= _balance(token1), 'M1');

    emit Mint(msg.sender, input.owner, input.tickLower, input.tickUpper, input.amount, amount0, amount1);
  }

  function burn(
    mapping(bytes32 => Position.Info) storage positions,
    mapping(int24 => Tick.Info) storage ticks,
    mapping(int16 => uint256) storage tickBitmap,
    Oracle.Observation[65_535] storage observations,
    CLPool.Slot0 storage slot0,
    ModifyPositionInput memory input
  ) external returns (uint128 liquidityAfter, uint256 amount0, uint256 amount1) {
    int256 amount0Int;
    int256 amount1Int;
    (liquidityAfter, amount0Int, amount1Int) =
      _modifyPosition(positions, ticks, tickBitmap, observations, slot0, input, -int256(input.amount).toInt128());

    amount0 = uint256(-amount0Int);
    amount1 = uint256(-amount1Int);

    if (amount0 > 0 || amount1 > 0) {
      _creditBurnedTokens(positions, input, uint128(amount0), uint128(amount1));
    }

    emit Burn(input.owner, input.tickLower, input.tickUpper, input.amount, amount0, amount1);
  }

  function _creditBurnedTokens(
    mapping(bytes32 => Position.Info) storage positions,
    ModifyPositionInput memory input,
    uint128 amount0,
    uint128 amount1
  ) private {
    Position.Info storage position = positions.get(input.owner, input.tickLower, input.tickUpper);
    (position.tokensOwed0, position.tokensOwed1) = (position.tokensOwed0 + amount0, position.tokensOwed1 + amount1);
  }

  function collect(
    mapping(bytes32 => Position.Info) storage positions,
    address recipient,
    int24 tickLower,
    int24 tickUpper,
    uint128 amount0Requested,
    uint128 amount1Requested,
    address owner,
    address token0,
    address token1
  ) external returns (uint128 amount0, uint128 amount1) {
    Position.Info storage position = positions.get(owner, tickLower, tickUpper);
    amount0 = amount0Requested > position.tokensOwed0 ? position.tokensOwed0 : amount0Requested;
    amount1 = amount1Requested > position.tokensOwed1 ? position.tokensOwed1 : amount1Requested;
    if (amount0 > 0) {
      position.tokensOwed0 -= amount0;
      TransferHelper.safeTransfer(token0, recipient, amount0);
    }
    if (amount1 > 0) {
      position.tokensOwed1 -= amount1;
      TransferHelper.safeTransfer(token1, recipient, amount1);
    }
    emit Collect(owner, recipient, tickLower, tickUpper, amount0, amount1);
  }

  function collectFees(
    CLPool.GaugeFees storage gaugeFees,
    address recipient,
    address token0,
    address token1
  ) external returns (uint128 amount0, uint128 amount1) {
    amount0 = gaugeFees.token0;
    amount1 = gaugeFees.token1;
    if (amount0 > 1) {
      gaugeFees.token0 = 1;
      TransferHelper.safeTransfer(token0, recipient, --amount0);
    } else {
      amount0 = 0;
    }
    if (amount1 > 1) {
      gaugeFees.token1 = 1;
      TransferHelper.safeTransfer(token1, recipient, --amount1);
    } else {
      amount1 = 0;
    }
    emit CollectFees(recipient, amount0, amount1);
  }

  function _modifyPosition(
    mapping(bytes32 => Position.Info) storage positions,
    mapping(int24 => Tick.Info) storage ticks,
    mapping(int16 => uint256) storage tickBitmap,
    Oracle.Observation[65_535] storage observations,
    CLPool.Slot0 storage slot0,
    ModifyPositionInput memory input,
    int128 liquidityDelta
  ) private returns (uint128 liquidityAfter, int256 amount0, int256 amount1) {
    _checkTicks(input.tickLower, input.tickUpper);

    CLPool.Slot0 memory currentSlot0 = slot0;
    _updatePosition(positions, ticks, tickBitmap, observations, currentSlot0, input, liquidityDelta);

    liquidityAfter = input.liquidity;
    if (liquidityDelta != 0) {
      if (currentSlot0.tick < input.tickLower) {
        amount0 = SqrtPriceMath.getAmount0Delta(
          TickMath.getSqrtRatioAtTick(input.tickLower), TickMath.getSqrtRatioAtTick(input.tickUpper), liquidityDelta
        );
      } else if (currentSlot0.tick < input.tickUpper) {
        (slot0.observationIndex, slot0.observationCardinality) = observations.write(
          currentSlot0.observationIndex,
          uint32(block.timestamp),
          currentSlot0.tick,
          input.liquidity,
          currentSlot0.observationCardinality,
          currentSlot0.observationCardinalityNext
        );

        amount0 = SqrtPriceMath.getAmount0Delta(
          currentSlot0.sqrtPriceX96, TickMath.getSqrtRatioAtTick(input.tickUpper), liquidityDelta
        );
        amount1 = SqrtPriceMath.getAmount1Delta(
          TickMath.getSqrtRatioAtTick(input.tickLower), currentSlot0.sqrtPriceX96, liquidityDelta
        );

        liquidityAfter = LiquidityMath.addDelta(input.liquidity, liquidityDelta);
      } else {
        amount1 = SqrtPriceMath.getAmount1Delta(
          TickMath.getSqrtRatioAtTick(input.tickLower), TickMath.getSqrtRatioAtTick(input.tickUpper), liquidityDelta
        );
      }
    }
  }

  function _updatePosition(
    mapping(bytes32 => Position.Info) storage positions,
    mapping(int24 => Tick.Info) storage ticks,
    mapping(int16 => uint256) storage tickBitmap,
    Oracle.Observation[65_535] storage observations,
    CLPool.Slot0 memory currentSlot0,
    ModifyPositionInput memory input,
    int128 liquidityDelta
  ) private {
    bool flippedLower;
    bool flippedUpper;
    if (liquidityDelta != 0) {
      PositionObservation memory observation;
      observation.currentTick = currentSlot0.tick;
      observation.liquidityDelta = liquidityDelta;
      (observation.tickCumulative, observation.secondsPerLiquidityCumulativeX128) = observations.observeSingle(
        uint32(block.timestamp),
        0,
        currentSlot0.tick,
        currentSlot0.observationIndex,
        input.liquidity,
        currentSlot0.observationCardinality
      );

      flippedLower = _updateLowerTick(ticks, input, observation);
      flippedUpper = _updateUpperTick(ticks, input, observation);

      if (flippedLower) tickBitmap.flipTick(input.tickLower, input.tickSpacing);
      if (flippedUpper) tickBitmap.flipTick(input.tickUpper, input.tickSpacing);
    }

    (uint256 feeGrowthInside0X128, uint256 feeGrowthInside1X128) = ticks.getFeeGrowthInside(
      input.tickLower, input.tickUpper, currentSlot0.tick, input.feeGrowthGlobal0X128, input.feeGrowthGlobal1X128
    );

    Position.Info storage position = positions.get(input.owner, input.tickLower, input.tickUpper);
    bool staked = (input.owner == input.gauge) && (input.owner != address(0));
    position.update(liquidityDelta, feeGrowthInside0X128, feeGrowthInside1X128, staked);

    if (liquidityDelta < 0) {
      if (flippedLower) ticks.clear(input.tickLower);
      if (flippedUpper) ticks.clear(input.tickUpper);
    }
  }

  function _updateLowerTick(
    mapping(int24 => Tick.Info) storage ticks,
    ModifyPositionInput memory input,
    PositionObservation memory observation
  ) private returns (bool) {
    return ticks.update(
      input.tickLower,
      observation.currentTick,
      observation.liquidityDelta,
      input.feeGrowthGlobal0X128,
      input.feeGrowthGlobal1X128,
      input.rewardGrowthGlobalX128,
      observation.secondsPerLiquidityCumulativeX128,
      observation.tickCumulative,
      uint32(block.timestamp),
      false,
      input.maxLiquidityPerTick
    );
  }

  function _updateUpperTick(
    mapping(int24 => Tick.Info) storage ticks,
    ModifyPositionInput memory input,
    PositionObservation memory observation
  ) private returns (bool) {
    return ticks.update(
      input.tickUpper,
      observation.currentTick,
      observation.liquidityDelta,
      input.feeGrowthGlobal0X128,
      input.feeGrowthGlobal1X128,
      input.rewardGrowthGlobalX128,
      observation.secondsPerLiquidityCumulativeX128,
      observation.tickCumulative,
      uint32(block.timestamp),
      true,
      input.maxLiquidityPerTick
    );
  }

  function validateGaugeFactory(address factoryRegistry, address factory) external view {
    address gaugeFactory = IFactoryRegistry(factoryRegistry).targetFactoryToGaugeFactory(factory);
    require(msg.sender == gaugeFactory, 'NGF');
  }

  function flash(
    CLPool.GaugeFees storage gaugeFees,
    FlashInput memory input,
    bytes calldata data
  ) external returns (uint256 feeGrowthDelta0, uint256 feeGrowthDelta1) {
    require(input.liquidity > 0, 'L');

    (uint256 fee0, uint256 fee1) = _flashFees(input, data);
    uint256 balance0Before = _balance(input.token0);
    uint256 balance1Before = _balance(input.token1);

    if (input.amount0 > 0) TransferHelper.safeTransfer(input.token0, input.recipient, input.amount0);
    if (input.amount1 > 0) TransferHelper.safeTransfer(input.token1, input.recipient, input.amount1);

    ICLFlashCallback(msg.sender).uniswapV3FlashCallback(fee0, fee1, data);

    uint256 paid0 = _paid(input.token0, balance0Before, fee0, 'F0');
    uint256 paid1 = _paid(input.token1, balance1Before, fee1, 'F1');

    feeGrowthDelta0 = _accrueGaugeFee(gaugeFees, input, paid0, true);
    feeGrowthDelta1 = _accrueGaugeFee(gaugeFees, input, paid1, false);

    emit Flash(msg.sender, input.recipient, input.amount0, input.amount1, paid0, paid1);
  }

  function _flashFees(FlashInput memory input, bytes memory data) private returns (uint256 fee0, uint256 fee1) {
    uint24 feePips = ICLFactory(input.factory)
      .getPoolSwapHook(address(this))
      .beforeFlash(
        ISwapHook.FlashParams({
          caller: msg.sender, recipient: input.recipient, amount0: input.amount0, amount1: input.amount1, data: data
        }),
        input.factory,
        input.tickSpacing
      );
    fee0 = FullMath.mulDivRoundingUp(input.amount0, feePips, SwapHookLib._DENOMINATOR);
    fee1 = FullMath.mulDivRoundingUp(input.amount1, feePips, SwapHookLib._DENOMINATOR);
  }

  function _balance(address token) private view returns (uint256) {
    (bool success, bytes memory data) =
      token.staticcall(abi.encodeWithSelector(IERC20Minimal.balanceOf.selector, address(this)));
    require(success && data.length >= 32);
    return abi.decode(data, (uint256));
  }

  function _paid(
    address token,
    uint256 balanceBefore,
    uint256 fee,
    string memory error
  ) private view returns (uint256) {
    uint256 balanceAfter = _balance(token);
    require(balanceBefore.add(fee) <= balanceAfter, error);
    return balanceAfter - balanceBefore;
  }

  function _accrueGaugeFee(
    CLPool.GaugeFees storage gaugeFees,
    FlashInput memory input,
    uint256 paid,
    bool zeroForOne
  ) private returns (uint256 feeGrowthDelta) {
    if (paid == 0) return 0;

    uint256 stakedFeeAmount;
    (feeGrowthDelta, stakedFeeAmount) = _calculateFees(paid, input.liquidity, input.stakedLiquidity, input.factory);
    if (uint128(stakedFeeAmount) > 0) {
      if (zeroForOne) gaugeFees.token0 += uint128(stakedFeeAmount);
      else gaugeFees.token1 += uint128(stakedFeeAmount);
    }
  }

  function _calculateFees(
    uint256 feeAmount,
    uint128 liquidity,
    uint128 stakedLiquidity,
    address factory
  ) private view returns (uint256 feeGrowthGlobalX128, uint256 stakedFeeAmount) {
    if (liquidity == stakedLiquidity) {
      stakedFeeAmount = feeAmount;
    } else if (stakedLiquidity == 0) {
      (uint256 unstakedFeeAmount, uint256 stakedFee) = _applyUnstakedFees(feeAmount, 0, factory);
      feeGrowthGlobalX128 = FullMath.mulDiv(unstakedFeeAmount, FixedPoint128.Q128, liquidity);
      stakedFeeAmount = stakedFee;
    } else {
      (uint256 unstakedFeeAmount, uint256 stakedFee) = _splitFees(feeAmount, liquidity, stakedLiquidity, factory);
      feeGrowthGlobalX128 = FullMath.mulDiv(unstakedFeeAmount, FixedPoint128.Q128, liquidity - stakedLiquidity);
      stakedFeeAmount = stakedFee;
    }
  }

  function _splitFees(
    uint256 feeAmount,
    uint128 liquidity,
    uint128 stakedLiquidity,
    address factory
  ) private view returns (uint256 unstakedFeeAmount, uint256 stakedFeeAmount) {
    stakedFeeAmount = FullMath.mulDivRoundingUp(feeAmount, stakedLiquidity, liquidity);
    return _applyUnstakedFees(feeAmount - stakedFeeAmount, stakedFeeAmount, factory);
  }

  function _applyUnstakedFees(
    uint256 unstakedFeeAmount,
    uint256 stakedFeeAmount,
    address factory
  ) private view returns (uint256, uint256) {
    uint256 stakedFee = FullMath.mulDivRoundingUp(
      unstakedFeeAmount, ICLFactory(factory).getUnstakedFee(address(this)), 1_000_000
    );
    return (unstakedFeeAmount - stakedFee, stakedFeeAmount + stakedFee);
  }
}
