"},"contracts/core/libraries/Oracle.sol":{"content":"// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0 <0.8.0;

/// @title Oracle
/// @notice Provides price and liquidity data useful for a wide variety of system designs
/// @dev Instances of stored oracle data, "observations", are collected in the oracle array
/// Every pool is initialized with an oracle array length of 1. Anyone can pay the SSTOREs to increase the
/// maximum length of the oracle array. New slots will be added when the array is fully populated.
/// Observations are overwritten when the full length of the oracle array is populated.
/// The most recent observation is available, independent of the length of the oracle array, by passing 0 to observe()
library Oracle {
  struct Observation {
    // the block timestamp of the observation
    uint32 blockTimestamp;
    // the tick accumulator, i.e. tick * time elapsed since the pool was first initialized
    int56 tickCumulative;
    // the seconds per liquidity, i.e. seconds elapsed / max(1, liquidity) since the pool was first initialized
    uint160 secondsPerLiquidityCumulativeX128;
    // whether or not the observation is initialized
    bool initialized;
  }

  /// @notice Transforms a previous observation into a new observation, given the passage of time and the current tick and liquidity values
  /// @dev blockTimestamp _must_ be chronologically equal to or greater than last.blockTimestamp, safe for 0 or 1 overflows
  /// @param last The specified observation to be transformed
  /// @param blockTimestamp The timestamp of the new observation
  /// @param tick The active tick at the time of the new observation
  /// @param liquidity The total in-range liquidity at the time of the new observation
  /// @return Observation The newly populated observation
  function transform(
    Observation memory last,
    uint32 blockTimestamp,
    int24 tick,
    uint128 liquidity
  ) private pure returns (Observation memory) {
    uint32 delta = blockTimestamp - last.blockTimestamp;
    return Observation({
      blockTimestamp: blockTimestamp,
      tickCumulative: last.tickCumulative + int56(tick) * delta,
      secondsPerLiquidityCumulativeX128: last.secondsPerLiquidityCumulativeX128
        + ((uint160(delta) << 128) / (liquidity > 0 ? liquidity : 1)),
      initialized: true
    });
  }

  /// @notice Initialize the oracle array by writing the first slot. Called once for the lifecycle of the observations array
  /// @param self The stored oracle array
  /// @param time The time of the oracle initialization, via block.timestamp truncated to uint32
  /// @return cardinality The number of populated elements in the oracle array
  /// @return cardinalityNext The new length of the oracle array, independent of population
  function initialize(
    Observation[65_535] storage self,
    uint32 time
  ) internal returns (uint16 cardinality, uint16 cardinalityNext) {
    self[0] = Observation({
      blockTimestamp: time, tickCumulative: 0, secondsPerLiquidityCumulativeX128: 0, initialized: true
    });
    return (1, 1);
  }

  /// @notice Writes an oracle observation to the array
  /// @dev Writable at most once per block. Index represents the most recently written element. cardinality and index must be tracked externally.
  /// If the index is at the end of the allowable array length (according to cardinality), and the next cardinality
  /// is greater than the current one, cardinality may be increased. This restriction is created to preserve ordering.
  /// @param self The stored oracle array
  /// @param index The index of the observation that was most recently written to the observations array
  /// @param blockTimestamp The timestamp of the new observation
  /// @param tick The active tick at the time of the new observation
  /// @param liquidity The total in-range liquidity at the time of the new observation
  /// @param cardinality The number of populated elements in the oracle array
  /// @param cardinalityNext The new length of the oracle array, independent of population
  /// @return indexUpdated The new index of the most recently written element in the oracle array
  /// @return cardinalityUpdated The new cardinality of the oracle array
  function write(
    Observation[65_535] storage self,
    uint16 index,
    uint32 blockTimestamp,
    int24 tick,
    uint128 liquidity,
    uint16 cardinality,
    uint16 cardinalityNext
  ) internal returns (uint16 indexUpdated, uint16 cardinalityUpdated) {
    Observation memory last = self[index];

    // early return if we've already written an observation this block
    if (last.blockTimestamp == blockTimestamp) return (index, cardinality);

    // if the conditions are right, we can bump the cardinality
    if (cardinalityNext > cardinality && index == (cardinality - 1)) {
      cardinalityUpdated = cardinalityNext;
    } else {
      cardinalityUpdated = cardinality;
    }

    indexUpdated = (index + 1) % cardinalityUpdated;
    self[indexUpdated] = transform(last, blockTimestamp, tick, liquidity);
  }

  /// @notice Prepares the oracle array to store up to `next` observations
  /// @param self The stored oracle array
  /// @param current The current next cardinality of the oracle array
  /// @param next The proposed next cardinality which will be populated in the oracle array
  /// @return next The next cardinality which will be populated in the oracle array
  function grow(Observation[65_535] storage self, uint16 current, uint16 next) internal returns (uint16) {
    require(current > 0, 'I');
    // no-op if the passed next value isn't greater than the current next value
    if (next <= current) return current;
    // store in each slot to prevent fresh SSTOREs in swaps
    // this data will not be used because the initialized boolean is still false
    for (uint16 i = current; i < next; i++) {
      self[i].blockTimestamp = 1;
    }
    return next;
  }

  /// @notice comparator for 32-bit timestamps
  /// @dev safe for 0 or 1 overflows, a and b _must_ be chronologically before or equal to time
  /// @param time A timestamp truncated to 32 bits
  /// @param a A comparison timestamp from which to determine the relative position of `time`
  /// @param b From which to determine the relative position of `time`
  /// @return bool Whether `a` is chronologically <= `b`
  function lte(uint32 time, uint32 a, uint32 b) private pure returns (bool) {
    // if there hasn't been overflow, no need to adjust
    if (a <= time && b <= time) return a <= b;

    uint256 aAdjusted = a > time ? a : a + 2 ** 32;
    uint256 bAdjusted = b > time ? b : b + 2 ** 32;

    return aAdjusted <= bAdjusted;
  }

  /// @notice Fetches the observations beforeOrAt and atOrAfter a target, i.e. where [beforeOrAt, atOrAfter] is satisfied.
  /// The result may be the same observation, or adjacent observations.
  /// @dev The answer must be contained in the array, used when the target is located within the stored observation
  /// boundaries: older than the most recent observation and younger, or the same age as, the oldest observation
  /// @param self The stored oracle array
  /// @param time The current block.timestamp
  /// @param target The timestamp at which the reserved observation should be for
  /// @param index The index of the observation that was most recently written to the observations array
  /// @param cardinality The number of populated elements in the oracle array
  /// @return beforeOrAt The observation recorded before, or at, the target
  /// @return atOrAfter The observation recorded at, or after, the target
  function binarySearch(
    Observation[65_535] storage self,
    uint32 time,
    uint32 target,
    uint16 index,
    uint16 cardinality
  ) private view returns (Observation memory beforeOrAt, Observation memory atOrAfter) {
    uint256 l = (index + 1) % cardinality; // oldest observation
    uint256 r = l + cardinality - 1; // newest observation
    uint256 i;
    while (true) {
      i = (l + r) / 2;

      beforeOrAt = self[i % cardinality];

      // we've landed on an uninitialized tick, keep searching higher (more recently)
      if (!beforeOrAt.initialized) {
        l = i + 1;
        continue;
      }

      atOrAfter = self[(i + 1) % cardinality];

      bool targetAtOrAfter = lte(time, beforeOrAt.blockTimestamp, target);

      // check if we've found the answer!
      if (targetAtOrAfter && lte(time, target, atOrAfter.blockTimestamp)) break;

      if (!targetAtOrAfter) r = i - 1;
      else l = i + 1;
    }
  }

  /// @notice Fetches the observations beforeOrAt and atOrAfter a given target, i.e. where [beforeOrAt, atOrAfter] is satisfied
  /// @dev Assumes there is at least 1 initialized observation.
  /// Used by observeSingle() to compute the counterfactual accumulator values as of a given block timestamp.
  /// @param self The stored oracle array
  /// @param time The current block.timestamp
  /// @param target The timestamp at which the reserved observation should be for
  /// @param tick The active tick at the time of the returned or simulated observation
  /// @param index The index of the observation that was most recently written to the observations array
  /// @param liquidity The total pool liquidity at the time of the call
  /// @param cardinality The number of populated elements in the oracle array
  /// @return beforeOrAt The observation which occurred at, or before, the given timestamp
  /// @return atOrAfter The observation which occurred at, or after, the given timestamp
  function getSurroundingObservations(
    Observation[65_535] storage self,
    uint32 time,
    uint32 target,
    int24 tick,
    uint16 index,
    uint128 liquidity,
    uint16 cardinality
  ) private view returns (Observation memory beforeOrAt, Observation memory atOrAfter) {
    // optimistically set before to the newest observation
    beforeOrAt = self[index];

    // if the target is chronologically at or after the newest observation, we can early return
    if (lte(time, beforeOrAt.blockTimestamp, target)) {
      if (beforeOrAt.blockTimestamp == target) {
        // if newest observation equals target, we're in the same block, so we can ignore atOrAfter
        return (beforeOrAt, atOrAfter);
      } else {
        // otherwise, we need to transform
        return (beforeOrAt, transform(beforeOrAt, target, tick, liquidity));
      }
    }

    // now, set before to the oldest observation
    beforeOrAt = self[(index + 1) % cardinality];
    if (!beforeOrAt.initialized) beforeOrAt = self[0];

    // ensure that the target is chronologically at or after the oldest observation
    require(lte(time, beforeOrAt.blockTimestamp, target), 'OLD');

    // if we've reached this point, we have to binary search
    return binarySearch(self, time, target, index, cardinality);
  }

  /// @dev Reverts if an observation at or before the desired observation timestamp does not exist.
  /// 0 may be passed as `secondsAgo' to return the current cumulative values.
  /// If called with a timestamp falling between two observations, returns the counterfactual accumulator values
  /// at exactly the timestamp between the two observations.
  /// @param self The stored oracle array
  /// @param time The current block timestamp
  /// @param secondsAgo The amount of time to look back, in seconds, at which point to return an observation
  /// @param tick The current tick
  /// @param index The index of the observation that was most recently written to the observations array
  /// @param liquidity The current in-range pool liquidity
  /// @param cardinality The number of populated elements in the oracle array
  /// @return tickCumulative The tick * time elapsed since the pool was first initialized, as of `secondsAgo`
  /// @return secondsPerLiquidityCumulativeX128 The time elapsed / max(1, liquidity) since the pool was first initialized, as of `secondsAgo`
  function observeSingle(
    Observation[65_535] storage self,
    uint32 time,
    uint32 secondsAgo,
    int24 tick,
    uint16 index,
    uint128 liquidity,
    uint16 cardinality
  ) internal view returns (int56 tickCumulative, uint160 secondsPerLiquidityCumulativeX128) {
    if (secondsAgo == 0) {
      Observation memory last = self[index];
      if (last.blockTimestamp != time) last = transform(last, time, tick, liquidity);
      return (last.tickCumulative, last.secondsPerLiquidityCumulativeX128);
    }

    uint32 target = time - secondsAgo;

    (Observation memory beforeOrAt, Observation memory atOrAfter) =
      getSurroundingObservations(self, time, target, tick, index, liquidity, cardinality);

    if (target == beforeOrAt.blockTimestamp) {
      // we're at the left boundary
      return (beforeOrAt.tickCumulative, beforeOrAt.secondsPerLiquidityCumulativeX128);
    } else if (target == atOrAfter.blockTimestamp) {
      // we're at the right boundary
      return (atOrAfter.tickCumulative, atOrAfter.secondsPerLiquidityCumulativeX128);
    } else {
      // we're in the middle
      uint32 observationTimeDelta = atOrAfter.blockTimestamp - beforeOrAt.blockTimestamp;
      uint32 targetDelta = target - beforeOrAt.blockTimestamp;
      return (
        beforeOrAt.tickCumulative + ((atOrAfter.tickCumulative - beforeOrAt.tickCumulative) / observationTimeDelta)
          * targetDelta,
        beforeOrAt.secondsPerLiquidityCumulativeX128
          + uint160(
            (uint256(atOrAfter.secondsPerLiquidityCumulativeX128 - beforeOrAt.secondsPerLiquidityCumulativeX128)
                * targetDelta) / observationTimeDelta
          )
      );
    }
  }

  /// @notice Returns the accumulator values as of each time seconds ago from the given time in the array of `secondsAgos`
  /// @dev Reverts if `secondsAgos` > oldest observation
  /// @param self The stored oracle array
  /// @param time The current block.timestamp
  /// @param secondsAgos Each amount of time to look back, in seconds, at which point to return an observation
  /// @param tick The current tick
  /// @param index The index of the observation that was most recently written to the observations array
  /// @param liquidity The current in-range pool liquidity
  /// @param cardinality The number of populated elements in the oracle array
  /// @return tickCumulatives The tick * time elapsed since the pool was first initialized, as of each `secondsAgo`
  /// @return secondsPerLiquidityCumulativeX128s The cumulative seconds / max(1, liquidity) since the pool was first initialized, as of each `secondsAgo`
  function observe(
    Observation[65_535] storage self,
    uint32 time,
    uint32[] memory secondsAgos,
    int24 tick,
    uint16 index,
    uint128 liquidity,
    uint16 cardinality
  ) internal view returns (int56[] memory tickCumulatives, uint160[] memory secondsPerLiquidityCumulativeX128s) {
    require(cardinality > 0, 'I');

    tickCumulatives = new int56[](secondsAgos.length);
    secondsPerLiquidityCumulativeX128s = new uint160[](secondsAgos.length);
    for (uint256 i = 0; i < secondsAgos.length; i++) {
      (tickCumulatives[i], secondsPerLiquidityCumulativeX128s[i]) =
        observeSingle(self, time, secondsAgos[i], tick, index, liquidity, cardinality);
    }
  }
}
"},"contracts/gauge/interfaces/ILeafVoter.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity >=0.7.6;
pragma abicoder v2;

import {IAccessControl} from './IAccessControl.sol';

interface ILeafVoter is IAccessControl {
  /**
   * @notice Aggregated voting power of a gauge at a point in time.
   * @param bias Decaying voting power at `ts`.
   * @param slope Per-second decay of `bias`.
   * @param ts Timestamp the point was resolved at.
   * @param permanentStakeBalance Non-decaying voting power from permanent stakes.
   */
  struct Point {
    int128 bias;
    int128 slope;
    uint48 ts;
    uint128 permanentStakeBalance;
  }

  /**
   * @notice Permissionless settle entrypoint for a registered gauge.
   *         Settles the chain index to `block.timestamp`, settles `_gauge`, and
   *         returns the gauge's cumulative reward share. The return value is
   *         monotonically increasing; a call against an unregistered gauge
   *         returns 0 without settling, so the function never reverts for any
   *         input address.
   * @param _gauge The gauge to settle.
   * @return _cumulativeRewardShare The gauge's settled cumulative reward share.
   */
  function settleGauge(address _gauge) external returns (uint256 _cumulativeRewardShare);

  /**
   * @notice Read-only twin of `settleGauge`. Projects the gauge's cumulative
   *         reward share at the current timestamp without writing state.
   *         `projectedCumulativeRewardShare(_gauge)` equals the value a
   *         `settleGauge(_gauge)` in this block would return.
   * @param _gauge The gauge to project.
   * @return _cumulativeRewardShare The gauge's projected cumulative reward share.
   */
  function projectedCumulativeRewardShare(address _gauge) external view returns (uint256 _cumulativeRewardShare);

  /**
   * @notice Mints `ReceiptToken` to the registered `EmissionsHandler` and calls it back per recipient.
   * @dev Reverts with `GaugeNotRegistered` for an unregistered caller and `CeilingExceeded` when the claim exceeds the
   * gauge's claimable headroom, `ceiling - claimed - surplus`. The claim is added to the gauge's `claimed` before the
   * mint, so all state effects complete before the handler callback fires. Callbacks MUST NOT rely on further
   * `LeafVoter` state changes. Emits `EmissionsMinted`.
   * @param _recipients Recipients for the per-leg delivery (LP, referral).
   * @param _amounts Per-leg amounts of `ReceiptToken`.
   */
  function mintEmissions(address[] calldata _recipients, uint128[] calldata _amounts) external;

  /**
   * @notice Gauge-only entrypoint for forfeiting surplus emissions the gauge
   *         cannot distribute, covering the Idle Gauge and Early Exit cases.
   *         Clamps `_amount` to the gauge's claimable headroom
   *         (`ceiling - claimed - surplus`), flushes the clamped amount into
   *         the gauge's `surplus` and the chain-level `surplusAccrued`, and
   *         emits `EmissionsForfeited` with the accrued amount. Reverts with
   *         `GaugeNotRegistered` when the caller is not a registered gauge.
   * @param _amount The surplus the calling gauge is forfeiting.
   */
  function forfeitEmissions(uint128 _amount) external;

  /**
   * @notice Whether a gauge is activated for direct allocation routing.
   * @param _gauge Gauge address to query.
   * @return Whether the gauge is activated.
   */
  function isActivated(address _gauge) external view returns (bool);

  /**
   * @notice Canonical per-gauge settlement state.
   * @param _gauge Gauge address to query.
   * @return _ceiling Cumulative effective share credited to the gauge.
   * @return _claimed Cumulative emissions minted to recipients by the claim flow.
   * @return _lastSettlement Timestamp of the gauge's last settlement.
   * @return _isRegistered Whether the gauge was produced by an approved factory.
   * @return _isActivated Whether the gauge is activated for direct allocation routing.
   * @return _surplus Cumulative surplus attributed to the gauge.
   * @return _lastIndex Snapshot of the chain index at the gauge's last settlement.
   * @return _lastTimeIndex Snapshot of the chain time index at the gauge's last settlement.
   * @return _point Decaying weight of the gauge.
   */
  function gaugeStates(address _gauge)
    external
    view
    returns (
      uint128 _ceiling,
      uint128 _claimed,
      uint48 _lastSettlement,
      bool _isRegistered,
      bool _isActivated,
      uint128 _surplus,
      uint256 _lastIndex,
      uint256 _lastTimeIndex,
      Point memory _point
    );
}
"},"contracts/gauge/interfaces/ICLPool.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity =0.7.6;

/// @title Minimal CLPool interface
/// @notice Used to support the integration with the core implementation
/// @dev For full context, please review the Uniswap implementation under GPL license.
interface ICLPool {
  function token0() external view returns (address);

  function token1() external view returns (address);

  function tickSpacing() external view returns (int24);

  /// @notice The reward growth as a Q128.128 rewards of emission collected per unit of liquidity for the entire life of the pool
  /// @dev This value can overflow the uint256
  function rewardGrowthGlobalX128() external view returns (uint256);

  /// @notice The currently in range staked liquidity available to the pool
  /// @dev This value has no relationship to the total staked liquidity across all ticks
  function stakedLiquidity() external view returns (uint128);

  /// @notice The amounts of token0 and token1 that are owed to the gauge
  /// @dev Gauge fees will never exceed uint128 max in either token
  function gaugeFees() external view returns (uint128 amount0, uint128 amount1);

  /// @notice Returns data about reward growth within a tick range.
  /// RewardGrowthGlobalX128 can be supplied as a parameter for claimable reward calculations.
  /// @dev Used in gauge reward/earned calculations
  /// @param tickLower The lower tick of the range
  /// @param tickUpper The upper tick of the range
  /// @param _rewardGrowthGlobalX128 a calculated rewardGrowthGlobalX128 or 0 (in case of 0 it means we use the rewardGrowthGlobalX128 from state)
  /// @return rewardGrowthInsideX128 The reward growth in the range
  function getRewardGrowthInside(
    int24 tickLower,
    int24 tickUpper,
    uint256 _rewardGrowthGlobalX128
  ) external view returns (uint256 rewardGrowthInsideX128);

  /// @notice Initialize gauge and nft manager
  /// @dev Callable only once, by the gauge factory
  /// @param _gauge The gauge corresponding to this pool
  /// @param _nft The position manager used for position management
  function setGaugeAndPositionManager(address _gauge, address _nft) external;

  /// @notice Convert existing liquidity into staked liquidity
  /// @notice Only callable by the gauge associated with this pool
  /// @param stakedLiquidityDelta The amount by which to increase or decrease the staked liquidity
  /// @param tickLower The lower tick of the position for which to stake liquidity
  /// @param tickUpper The upper tick of the position for which to stake liquidity
  function stake(int128 stakedLiquidityDelta, int24 tickLower, int24 tickUpper) external;

  /// @notice Settle the pool's reward growth to the current block timestamp and return the accrued rollover
  /// @return _rollover Emissions accrued while no staked liquidity was in range. Reset to 0 after this call.
  function settleToBlock() external returns (uint256 _rollover);

  /// @notice Collect the gauge fee accrued to the pool
  /// @param recipient The address that receives the claimed gauge fees
  /// @return amount0 The gauge fee collected in token0
  /// @return amount1 The gauge fee collected in token1
  function collectFees(address recipient) external returns (uint128 amount0, uint128 amount1);
}
"},"contracts/core/CLPool.sol":{"content":"// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity =0.7.6;
pragma abicoder v2;

import './interfaces/ICLPool.sol';

import './libraries/LowGasSafeMath.sol';
import './libraries/Oracle.sol';
import './libraries/Position.sol';
import './libraries/SafeCast.sol';
import './libraries/Tick.sol';
import './libraries/TickBitmap.sol';

import {CLPoolNonSwapPath as CL} from './libraries/CLPoolNonSwapPath.sol';
import './libraries/FixedPoint128.sol';
import './libraries/FullMath.sol';
import './libraries/LiquidityMath.sol';
import './libraries/SwapMath.sol';
import './libraries/TickMath.sol';
import './libraries/TransferHelper.sol';
import './libraries/hook/SwapHookLib.sol';

import './interfaces/ICLFactory.sol';
import './interfaces/IERC20Minimal.sol';
import './interfaces/IFactoryRegistry.sol';
import './interfaces/callback/ICLSwapCallback.sol';
import './interfaces/hook/ISwapHook.sol';
import {ICLGauge} from 'contracts/gauge/interfaces/ICLGauge.sol';

contract CLPool is ICLPool {
  using LowGasSafeMath for uint256;
  using LowGasSafeMath for int256;
  using SafeCast for uint256;
  using SafeCast for int256;
  using Tick for mapping(int24 => Tick.Info);
  using TickBitmap for mapping(int16 => uint256);
  using Position for mapping(bytes32 => Position.Info);
  using Position for Position.Info;
  using Oracle for Oracle.Observation[65_535];
  using SwapHookLib for address;

  /// @inheritdoc ICLPoolConstants
  address public override factory;
  /// @inheritdoc ICLPoolConstants
  address public override token0;
  /// @inheritdoc ICLPoolConstants
  address public override token1;
  /// @inheritdoc ICLPoolConstants
  address public override gauge;
  /// @inheritdoc ICLPoolConstants
  address public override nft;
  /// @inheritdoc ICLPoolConstants
  address public override factoryRegistry;

  struct Slot0 {
    // the current price
    uint160 sqrtPriceX96;
    // the current tick
    int24 tick;
    // the most-recently updated index of the observations array
    uint16 observationIndex;
    // the current maximum number of observations that are being stored
    uint16 observationCardinality;
    // the next maximum number of observations to store, triggered in observations.write
    uint16 observationCardinalityNext;
    // whether the pool is locked
    bool unlocked;
  }

  /// @inheritdoc ICLPoolState
  Slot0 public override slot0;

  /// @inheritdoc ICLPoolState
  uint256 public override feeGrowthGlobal0X128;
  /// @inheritdoc ICLPoolState
  uint256 public override feeGrowthGlobal1X128;

  /// @inheritdoc ICLPoolState
  uint256 public override rewardGrowthGlobalX128;

  // accumulated gauge fees in token0/token1 units
  struct GaugeFees {
    uint128 token0;
    uint128 token1;
  }

  /// @inheritdoc ICLPoolState
  GaugeFees public override gaugeFees;

  /// @inheritdoc ICLPoolState
  uint256 public override rollover;

  /// @inheritdoc ICLPoolState
  uint128 public override stakedLiquidity;
  /// @inheritdoc ICLPoolState
  uint48 public override lastUpdated;
  /// @inheritdoc ICLPoolConstants
  int24 public override tickSpacing;

  /// @inheritdoc ICLPoolState
  uint128 public override liquidity;
  /// @inheritdoc ICLPoolConstants
  uint128 public override maxLiquidityPerTick;

  /// @inheritdoc ICLPoolState
  mapping(int24 => Tick.Info) public override ticks;
  /// @inheritdoc ICLPoolState
  mapping(int16 => uint256) public override tickBitmap;
  /// @inheritdoc ICLPoolState
  mapping(bytes32 => Position.Info) public override positions;
  /// @inheritdoc ICLPoolState
  Oracle.Observation[65_535] public override observations;

  /// @inheritdoc ICLPoolState
  uint160 public override secondsPerStakedLiquidityCumulativeX128;

  /// @inheritdoc ICLPoolConstants
  uint256 public constant override SWAP_FEE_CEIL = 100_000;
  /// @inheritdoc ICLPoolConstants
  uint256 public constant override DENOMINATOR = 1_000_000;
  /// @inheritdoc ICLPoolConstants
  bytes32 public constant override POOL_TYPE = 'CL';

  /// @dev Mutually exclusive reentrancy protection into the pool to/from a method. This method also prevents entrance
  /// to a function before the pool is initialized. The reentrancy guard is required throughout the contract because
  /// we use balance checks to determine the payment status of interactions such as mint, swap and flash.
  function _lock() private {
    _require(slot0.unlocked, 'LOK');
    slot0.unlocked = false;
  }

  function _unlock() private {
    slot0.unlocked = true;
  }

  function _require(bool condition, string memory error) private pure {
    require(condition, error);
  }

  /// @dev Prevents calling a function from anyone except the gauge associated with this pool
  function _onlyGauge() private view {
    _require(msg.sender == gauge, 'NG');
  }

  /// @dev Prevents calling a function from anyone except the nft manager
  function _onlyNftManager() private view {
    _require(msg.sender == nft, 'NNFT');
  }

  /// @inheritdoc ICLPoolActions
  function initialize(
    address _factory,
    address _token0,
    address _token1,
    int24 _tickSpacing,
    address _factoryRegistry,
    uint160 _sqrtPriceX96
  ) external override {
    require(factory == address(0) && _factory != address(0));
    factory = _factory;
    token0 = _token0;
    token1 = _token1;
    tickSpacing = _tickSpacing;
    factoryRegistry = _factoryRegistry;

    maxLiquidityPerTick =
      CL.initializeSlot0(slot0, observations, _sqrtPriceX96, TickMath.getTickAtSqrtRatio(_sqrtPriceX96), _tickSpacing);
  }

  /// @inheritdoc ICLPoolState
  function beforeSwapFee(ISwapHook.SwapParams memory _swapParams) public view override returns (uint24) {
    return CL.beforeSwapFee(_swapParams, factory, tickSpacing);
  }

  /// @inheritdoc ICLPoolState
  function afterSwapFee(
    ISwapHook.SwapParams memory _swapParams,
    ISwapHook.AfterSwapParams memory _afterSwapParams
  ) external view override returns (uint24) {
    return CL.afterSwapFee(_swapParams, _afterSwapParams, factory);
  }

  /// @inheritdoc ICLPoolState
  function flashFee(ISwapHook.FlashParams memory _flashParams) external view override returns (uint24 _fee) {
    return CL.flashFee(_flashParams, factory, tickSpacing);
  }

  /// @inheritdoc ICLPoolState
  /// @dev This method can be used for "legacy" swap fee modules.
  function fee() external view override returns (uint24) {
    ISwapHook.SwapParams memory _swapParams;
    _swapParams.caller = msg.sender;
    return beforeSwapFee(_swapParams);
  }

  /// @inheritdoc ICLPoolState
  function unstakedFee() public view override returns (uint24) {
    return ICLFactory(factory).getUnstakedFee(address(this));
  }

  /// @dev Common checks for valid tick inputs.
  function checkTicks(int24 tickLower, int24 tickUpper) private pure {
    require(tickLower < tickUpper, 'TLU');
    require(tickLower >= TickMath.MIN_TICK, 'TLM');
    require(tickUpper <= TickMath.MAX_TICK, 'TUM');
  }

  /// @dev Get the pool's balance of token0
  /// @dev This function is gas optimized to avoid a redundant extcodesize check in addition to the returndatasize
  /// check
  function balance0() private view returns (uint256) {
    return IERC20Minimal(token0).balanceOf(address(this));
  }

  /// @dev Get the pool's balance of token1
  /// @dev This function is gas optimized to avoid a redundant extcodesize check in addition to the returndatasize
  /// check
  function balance1() private view returns (uint256) {
    return IERC20Minimal(token1).balanceOf(address(this));
  }

  /// @inheritdoc ICLPoolDerivedState
  function snapshotCumulativesInside(
    int24 tickLower,
    int24 tickUpper
  )
    external
    view
    override
    returns (int56 tickCumulativeInside, uint160 secondsPerLiquidityInsideX128, uint32 secondsInside)
  {
    Slot0 memory currentSlot0 = slot0;
    return CL.snapshotCumulativesInside(
      ticks,
      observations,
      tickLower,
      tickUpper,
      currentSlot0.tick,
      currentSlot0.observationIndex,
      currentSlot0.observationCardinality,
      liquidity
    );
  }

  /// @inheritdoc ICLPoolDerivedState
  function observe(uint32[] calldata secondsAgos)
    external
    view
    override
    returns (int56[] memory tickCumulatives, uint160[] memory secondsPerLiquidityCumulativeX128s)
  {
    return observations.observe(
      uint32(block.timestamp), secondsAgos, slot0.tick, slot0.observationIndex, liquidity, slot0.observationCardinality
    );
  }

  /// @inheritdoc ICLPoolDerivedState
  function getSecondsPerStakedLiquidityCumulativeX128() external view override returns (uint160 _cumulative) {
    _cumulative = secondsPerStakedLiquidityCumulativeX128;
    uint128 _stakedLiquidity = stakedLiquidity;
    if (_stakedLiquidity > 0) {
      _cumulative += _secondsPerStakedLiquidityDelta(block.timestamp - lastUpdated, _stakedLiquidity);
    }
  }

  /// @inheritdoc ICLPoolActions
  function increaseObservationCardinalityNext(uint16 observationCardinalityNext) external override {
    _lock();
    CL.increaseObservationCardinalityNext(observations, slot0, observationCardinalityNext);
    _unlock();
  }

  /// @inheritdoc ICLPoolState
  function getFeeGrowthInside(
    int24 tickLower,
    int24 tickUpper
  ) external view override returns (uint256 feeGrowthInside0X128, uint256 feeGrowthInside1X128) {
    return CL.getFeeGrowthInside(ticks, tickLower, tickUpper, slot0.tick, feeGrowthGlobal0X128, feeGrowthGlobal1X128);
  }

  function _modifyPositionInput(
    address owner,
    int24 tickLower,
    int24 tickUpper
  ) private view returns (CL.ModifyPositionInput memory input) {
    input = CL.ModifyPositionInput({
      owner: owner,
      tickLower: tickLower,
      tickUpper: tickUpper,
      liquidity: liquidity,
      maxLiquidityPerTick: maxLiquidityPerTick,
      feeGrowthGlobal0X128: feeGrowthGlobal0X128,
      feeGrowthGlobal1X128: feeGrowthGlobal1X128,
      rewardGrowthGlobalX128: rewardGrowthGlobalX128,
      gauge: gauge,
      tickSpacing: tickSpacing,
      amount: 0
    });
  }

  /// @inheritdoc ICLPoolActions
  function mint(
    address recipient,
    int24 tickLower,
    int24 tickUpper,
    uint128 amount,
    bytes calldata data
  ) external override returns (uint256 amount0, uint256 amount1) {
    _lock();
    CL.ModifyPositionInput memory input = _modifyPositionInput(recipient, tickLower, tickUpper);
    input.amount = amount;
    (uint128 liquidityAfter, uint256 amount0Out, uint256 amount1Out) =
      CL.modifyPositionForMint(positions, ticks, tickBitmap, observations, slot0, input);
    liquidity = liquidityAfter;
    CL.settleMint(input, amount0Out, amount1Out, token0, token1, data);
    _unlock();
    return (amount0Out, amount1Out);
  }

  /// @inheritdoc ICLPoolActions
  function collect(
    address recipient,
    int24 tickLower,
    int24 tickUpper,
    uint128 amount0Requested,
    uint128 amount1Requested
  ) external override returns (uint128 amount0, uint128 amount1) {
    _lock();
    (amount0, amount1) = _collect({
      recipient: recipient,
      tickLower: tickLower,
      tickUpper: tickUpper,
      amount0Requested: amount0Requested,
      amount1Requested: amount1Requested,
      owner: msg.sender
    });
    _unlock();
  }

  /// @inheritdoc ICLPoolActions
  function collect(
    address recipient,
    int24 tickLower,
    int24 tickUpper,
    uint128 amount0Requested,
    uint128 amount1Requested,
    address owner
  ) external override returns (uint128 amount0, uint128 amount1) {
    _lock();
    _onlyNftManager();
    (amount0, amount1) = _collect({
      recipient: recipient,
      tickLower: tickLower,
      tickUpper: tickUpper,
      amount0Requested: amount0Requested,
      amount1Requested: amount1Requested,
      owner: owner
    });
    _unlock();
  }

  function _collect(
    address recipient,
    int24 tickLower,
    int24 tickUpper,
    uint128 amount0Requested,
    uint128 amount1Requested,
    address owner
  ) private returns (uint128 amount0, uint128 amount1) {
    return CL.collect(
      positions, recipient, tickLower, tickUpper, amount0Requested, amount1Requested, owner, token0, token1
    );
  }

  /// @inheritdoc ICLPoolActions
  function burn(
    int24 tickLower,
    int24 tickUpper,
    uint128 amount
  ) external override returns (uint256 amount0, uint256 amount1) {
    _lock();
    (amount0, amount1) = _burn({tickLower: tickLower, tickUpper: tickUpper, amount: amount, owner: msg.sender});
    _unlock();
  }

  /// @inheritdoc ICLPoolActions
  function burn(
    int24 tickLower,
    int24 tickUpper,
    uint128 amount,
    address owner
  ) external override returns (uint256 amount0, uint256 amount1) {
    _lock();
    _onlyNftManager();
    (amount0, amount1) = _burn({tickLower: tickLower, tickUpper: tickUpper, amount: amount, owner: owner});
    _unlock();
  }

  function _burn(
    int24 tickLower,
    int24 tickUpper,
    uint128 amount,
    address owner
  ) private returns (uint256 amount0, uint256 amount1) {
    CL.ModifyPositionInput memory input = _modifyPositionInput(owner, tickLower, tickUpper);
    input.amount = amount;
    (uint128 liquidityAfter, uint256 amount0Out, uint256 amount1Out) =
      CL.burn(positions, ticks, tickBitmap, observations, slot0, input);
    liquidity = liquidityAfter;
    return (amount0Out, amount1Out);
  }

  /// @inheritdoc ICLPoolActions
  function stake(int128 stakedLiquidityDelta, int24 tickLower, int24 tickUpper) external override {
    _lock();
    _onlyGauge();
    int24 tick = slot0.tick;
    // Increase staked liquidity in the current tick
    if (tick >= tickLower && tick < tickUpper) {
      _settleToBlock();
      stakedLiquidity = LiquidityMath.addDelta(stakedLiquidity, stakedLiquidityDelta);
    }

    CL.stakePositions(
      positions,
      ticks,
      nft,
      tickLower,
      tickUpper,
      tick,
      stakedLiquidityDelta,
      feeGrowthGlobal0X128,
      feeGrowthGlobal1X128
    );
    _unlock();
  }

  struct SwapCache {
    // liquidity at the beginning of the swap
    uint128 liquidityStart;
    // staked liquidity at the beginning of the swap
    uint128 stakedLiquidityStart;
    // the timestamp of the current block
    uint32 blockTimestamp;
    // the current value of the tick accumulator, computed only if we cross an initialized tick
    int56 tickCumulative;
    // the current value of seconds per liquidity accumulator, computed only if we cross an initialized tick
    uint160 secondsPerLiquidityCumulativeX128;
    // whether we've computed and cached the above two accumulators
    bool computedLatestObservation;
    // global swap hook used to call beforeSwap/afterSwap methods.
    address swapHook;
  }

  // the top level state of the swap, the results of which are recorded in storage at the end
  struct SwapState {
    // the amount remaining to be swapped in/out of the input/output asset
    int256 amountSpecifiedRemaining;
    // the amount already swapped out/in of the output/input asset
    int256 amountCalculated;
    // current sqrt(price)
    uint160 sqrtPriceX96;
    // the tick associated with the current price
    int24 tick;
    // the fee associated with the pool
    uint24 fee;
    // wether we've updated the fees in the current swap
    bool hasUpdatedFees;
    // the global fee growth of the input token
    uint256 feeGrowthGlobalX128;
    // amount of input token paid as gauge fee
    uint128 gaugeFee;
    // the current liquidity in range
    uint128 liquidity;
    // the current staked liquidity in range
    uint128 stakedLiquidity;
  }

  struct StepComputations {
    // the price at the beginning of the step
    uint160 sqrtPriceStartX96;
    // the next tick to swap to from the current tick in the swap direction
    int24 tickNext;
    // whether tickNext is initialized or not
    bool initialized;
    // sqrt(price) for the next tick (1/0)
    uint160 sqrtPriceNextX96;
    // how much is being swapped in in this step
    uint256 amountIn;
    // how much is being swapped out
    uint256 amountOut;
    // how much fee is being paid in
    uint256 feeAmount;
  }

  /// @inheritdoc ICLPoolActions
  function swap(
    address recipient,
    bool zeroForOne,
    int256 amountSpecified,
    uint160 sqrtPriceLimitX96,
    bytes calldata data
  ) external override returns (int256 amount0, int256 amount1) {
    _require(amountSpecified != 0, 'AS');

    Slot0 memory slot0Start = slot0;

    _require(slot0Start.unlocked, 'LOK');
    _require(
      zeroForOne
        ? sqrtPriceLimitX96 < slot0Start.sqrtPriceX96 && sqrtPriceLimitX96 > TickMath.MIN_SQRT_RATIO
        : sqrtPriceLimitX96 > slot0Start.sqrtPriceX96 && sqrtPriceLimitX96 < TickMath.MAX_SQRT_RATIO,
      'SPL'
    );

    slot0.unlocked = false;

    SwapCache memory cache = SwapCache({
      liquidityStart: liquidity,
      stakedLiquidityStart: stakedLiquidity,
      blockTimestamp: uint32(block.timestamp),
      secondsPerLiquidityCumulativeX128: 0,
      tickCumulative: 0,
      computedLatestObservation: false,
      swapHook: ICLFactory(factory).getPoolSwapHook(address(this))
    });

    bool exactInput = amountSpecified > 0;

    SwapState memory state = SwapState({
      amountSpecifiedRemaining: amountSpecified,
      amountCalculated: 0,
      sqrtPriceX96: slot0Start.sqrtPriceX96,
      tick: slot0Start.tick,
      fee: 0, // set below
      hasUpdatedFees: false,
      feeGrowthGlobalX128: zeroForOne ? feeGrowthGlobal0X128 : feeGrowthGlobal1X128,
      gaugeFee: 0,
      liquidity: cache.liquidityStart,
      stakedLiquidity: cache.stakedLiquidityStart
    });

    state.fee = cache.swapHook
      .beforeSwap(
        ISwapHook.SwapParams({
          caller: msg.sender,
          recipient: recipient,
          zeroForOne: zeroForOne,
          amountSpecified: amountSpecified,
          sqrtPriceLimitX96: sqrtPriceLimitX96,
          data: data,
          sqrtPriceX96: slot0Start.sqrtPriceX96,
          tick: slot0Start.tick
        }),
        factory,
        tickSpacing
      );

    // continue swapping as long as we haven't used the entire input/output and haven't reached the price limit
    while (state.amountSpecifiedRemaining != 0 && state.sqrtPriceX96 != sqrtPriceLimitX96) {
      StepComputations memory step;

      step.sqrtPriceStartX96 = state.sqrtPriceX96;

      (step.tickNext, step.initialized) =
        tickBitmap.nextInitializedTickWithinOneWord(state.tick, tickSpacing, zeroForOne);

      // ensure that we do not overshoot the min/max tick, as the tick bitmap is not aware of these bounds
      if (step.tickNext < TickMath.MIN_TICK) {
        step.tickNext = TickMath.MIN_TICK;
      } else if (step.tickNext > TickMath.MAX_TICK) {
        step.tickNext = TickMath.MAX_TICK;
      }

      // get the price for the next tick
      step.sqrtPriceNextX96 = TickMath.getSqrtRatioAtTick(step.tickNext);

      // compute values to swap to the target tick, price limit, or point where input/output amount is exhausted
      (state.sqrtPriceX96, step.amountIn, step.amountOut, step.feeAmount) = SwapMath.computeSwapStep(
        state.sqrtPriceX96,
        (zeroForOne ? step.sqrtPriceNextX96 < sqrtPriceLimitX96 : step.sqrtPriceNextX96 > sqrtPriceLimitX96)
          ? sqrtPriceLimitX96
          : step.sqrtPriceNextX96,
        state.liquidity,
        state.amountSpecifiedRemaining,
        state.fee
      );

      if (exactInput) {
        state.amountSpecifiedRemaining -= (step.amountIn + step.feeAmount).toInt256();
        state.amountCalculated = state.amountCalculated.sub(step.amountOut.toInt256());
      } else {
        state.amountSpecifiedRemaining += step.amountOut.toInt256();
        state.amountCalculated = state.amountCalculated.add((step.amountIn + step.feeAmount).toInt256());
      }

      // update global fee tracker and gauge fee
      if (state.liquidity > 0) {
        (uint256 _feeGrowthGlobalX128, uint256 _stakedFeeAmount) =
          calculateFees(step.feeAmount, state.liquidity, state.stakedLiquidity);

        state.feeGrowthGlobalX128 += _feeGrowthGlobalX128;
        state.gaugeFee += uint128(_stakedFeeAmount);
      }

      // shift tick if we reached the next price
      if (state.sqrtPriceX96 == step.sqrtPriceNextX96) {
        // if the tick is initialized, run the tick transition
        if (step.initialized) {
          // check for the placeholder value, which we replace with the actual value the first time the swap
          // crosses an initialized tick
          if (!cache.computedLatestObservation) {
            (cache.tickCumulative, cache.secondsPerLiquidityCumulativeX128) = observations.observeSingle(
              cache.blockTimestamp,
              0,
              slot0Start.tick,
              slot0Start.observationIndex,
              cache.liquidityStart,
              slot0Start.observationCardinality
            );
            cache.computedLatestObservation = true;
          }
          if (!state.hasUpdatedFees) {
            _settleToBlock();
            state.hasUpdatedFees = true;
          }
          Tick.LiquidityNets memory nets = ticks.cross(
            step.tickNext,
            (zeroForOne ? state.feeGrowthGlobalX128 : feeGrowthGlobal0X128),
            (zeroForOne ? feeGrowthGlobal1X128 : state.feeGrowthGlobalX128),
            cache.secondsPerLiquidityCumulativeX128,
            cache.tickCumulative,
            cache.blockTimestamp,
            rewardGrowthGlobalX128
          );
          // if we're moving leftward, we interpret liquidityNet & stakedLiquidityNet as the opposite sign
          // safe because liquidityNet & stakedLiquidityNet cannot be type(int128).min
          if (zeroForOne) {
            nets.liquidityNet = -nets.liquidityNet;
            nets.stakedLiquidityNet = -nets.stakedLiquidityNet;
          }

          state.liquidity = LiquidityMath.addDelta(state.liquidity, nets.liquidityNet);
          state.stakedLiquidity = LiquidityMath.addDelta(state.stakedLiquidity, nets.stakedLiquidityNet);
        }

        state.tick = zeroForOne ? step.tickNext - 1 : step.tickNext;
      } else if (state.sqrtPriceX96 != step.sqrtPriceStartX96) {
        // recompute unless we're on a lower tick boundary (i.e. already transitioned ticks), and haven't moved
        state.tick = TickMath.getTickAtSqrtRatio(state.sqrtPriceX96);
      }
    }

    /// @dev This function is able to mutate `gaugeFees` storage variable.
    cache.swapHook
      .afterSwap(
        ISwapHook.SwapParams({
          caller: msg.sender,
          recipient: recipient,
          zeroForOne: zeroForOne,
          amountSpecified: amountSpecified,
          sqrtPriceLimitX96: sqrtPriceLimitX96,
          data: data,
          sqrtPriceX96: state.sqrtPriceX96,
          tick: state.tick
        }),
        state,
        cache,
        gaugeFees
      );

    // update tick and write an oracle entry if the tick change
    if (state.tick != slot0Start.tick) {
      (uint16 observationIndex, uint16 observationCardinality) = observations.write(
        slot0Start.observationIndex,
        cache.blockTimestamp,
        slot0Start.tick,
        cache.liquidityStart,
        slot0Start.observationCardinality,
        slot0Start.observationCardinalityNext
      );
      (slot0.sqrtPriceX96, slot0.tick, slot0.observationIndex, slot0.observationCardinality) =
      (state.sqrtPriceX96, state.tick, observationIndex, observationCardinality);
    } else {
      // otherwise just update the price
      slot0.sqrtPriceX96 = state.sqrtPriceX96;
    }

    // update liquidity and stakedLiquidity if it changed
    if (cache.liquidityStart != state.liquidity) liquidity = state.liquidity;
    if (cache.stakedLiquidityStart != state.stakedLiquidity) stakedLiquidity = state.stakedLiquidity;

    // update fee growth global and, if necessary, gauge fees
    // overflow is acceptable, protocol has to withdraw before it hits type(uint128).max fees
    if (zeroForOne) {
      feeGrowthGlobal0X128 = state.feeGrowthGlobalX128;
      if (state.gaugeFee > 0) gaugeFees.token0 += state.gaugeFee;
    } else {
      feeGrowthGlobal1X128 = state.feeGrowthGlobalX128;
      if (state.gaugeFee > 0) gaugeFees.token1 += state.gaugeFee;
    }

    (amount0, amount1) = zeroForOne == exactInput
      ? (amountSpecified - state.amountSpecifiedRemaining, state.amountCalculated)
      : (state.amountCalculated, amountSpecified - state.amountSpecifiedRemaining);

    // do the transfers and collect payment
    if (zeroForOne) {
      if (amount1 < 0) TransferHelper.safeTransfer(token1, recipient, uint256(-amount1));

      uint256 balance0Before = balance0();
      ICLSwapCallback(msg.sender).uniswapV3SwapCallback(amount0, amount1, data);
      _require(balance0Before.add(uint256(amount0)) <= balance0(), 'IIA');
    } else {
      if (amount0 < 0) TransferHelper.safeTransfer(token0, recipient, uint256(-amount0));

      uint256 balance1Before = balance1();
      ICLSwapCallback(msg.sender).uniswapV3SwapCallback(amount0, amount1, data);
      _require(balance1Before.add(uint256(amount1)) <= balance1(), 'IIA');
    }

    emit Swap(msg.sender, recipient, amount0, amount1, state.sqrtPriceX96, state.liquidity, state.tick);
    slot0.unlocked = true;
  }

  /// @inheritdoc ICLPoolActions
  function flash(address recipient, uint256 amount0, uint256 amount1, bytes calldata data) external override {
    _lock();

    /// @dev The internal call credits part of the paid fee to gauge's token0/1.
    ///      And thus changes the original sequence of fee updates from:
    ///       1) getUnstakedFee() -> feeGrowthGlobal0X128 += x  -> gaugeFees.token0 += y
    ///       2) getUnstakedFee() -> feeGrowthGlobal1X128 += x' -> gaugeFees.token1 += y'
    ///      to:
    ///       1) getUnstakedFee() -> gaugeFees.token0 += y
    ///       2) getUnstakedFee() -> gaugeFees.token1 += y'
    ///       3) feeGrowthGlobal0X128 += x
    ///       4) feeGrowthGlobal1X128 += x'
    (uint256 feeGrowthDelta0, uint256 feeGrowthDelta1) = CL.flash(
      gaugeFees,
      CL.FlashInput({
        token0: token0,
        token1: token1,
        factory: factory,
        tickSpacing: tickSpacing,
        liquidity: liquidity,
        stakedLiquidity: stakedLiquidity,
        recipient: recipient,
        amount0: amount0,
        amount1: amount1
      }),
      data
    );
    if (feeGrowthDelta0 > 0) feeGrowthGlobal0X128 += feeGrowthDelta0;
    if (feeGrowthDelta1 > 0) feeGrowthGlobal1X128 += feeGrowthDelta1;
    _unlock();
  }

  /// @inheritdoc ICLPoolState
  function getRewardGrowthInside(
    int24 tickLower,
    int24 tickUpper,
    uint256 _rewardGrowthGlobalX128
  ) external view override returns (uint256 rewardGrowthInside) {
    return CL.getRewardGrowthInside(
      ticks, tickLower, tickUpper, slot0.tick, _rewardGrowthGlobalX128, rewardGrowthGlobalX128
    );
  }

  /// @dev Seconds elapsed converted into X128 seconds per unit of staked liquidity.
  function _secondsPerStakedLiquidityDelta(uint256 _elapsed, uint128 _stakedLiquidity) internal pure returns (uint160) {
    return uint160((_elapsed << 128) / _stakedLiquidity);
  }

  /// @dev Credits realized emissions to the accumulator when staked liquidity is in range, otherwise banks
  ///      them into rollover, then advances the settlement timestamp. Both settlement paths terminate here.
  function _updateRewardsGrowthGlobal(uint256 _rewardsToDistribute, uint48 _now, uint48 _lastUpdated) internal {
    uint128 _stakedLiquidity = stakedLiquidity;
    if (_stakedLiquidity > 0) {
      rewardGrowthGlobalX128 += FullMath.mulDiv(_rewardsToDistribute, FixedPoint128.Q128, _stakedLiquidity);
      secondsPerStakedLiquidityCumulativeX128 += _secondsPerStakedLiquidityDelta(_now - _lastUpdated, _stakedLiquidity);
    } else {
      rollover += _rewardsToDistribute;
    }
    lastUpdated = _now;
  }

  /// @dev Realizes rewards up to the current block by pulling the emissions accrued since the last
  /// settlement through the gauge. Calls {_updateRewardsGrowthGlobal} to update the rewards to
  /// distribute and lastUpdated. The LeafVoter's settlement is permissionless and returns 0 for
  /// unregistered gauges, so the gauge pull reverts in exactly one case: the gauge's factory relays
  /// the settle to the gauge tape inside a gas-capped call, and the caller funded the settle but
  /// not that capped subcall.
  function _settleToBlock() internal {
    uint48 _timestamp = uint48(block.timestamp);
    uint48 _lastUpdated = lastUpdated;
    if (_timestamp == _lastUpdated) return;

    address _gauge = gauge;
    if (_gauge == address(0)) return;

    uint256 _rewardsToDistribute = ICLGauge(_gauge).settleGauge();
    _updateRewardsGrowthGlobal(_rewardsToDistribute, _timestamp, _lastUpdated);
  }

  /// @inheritdoc ICLPoolActions
  function settleToBlock() external override returns (uint256 _rollover) {
    _lock();
    _onlyGauge();
    _settleToBlock();
    _rollover = rollover;
    delete rollover;
    _unlock();
  }

  /// @notice Calculates the fees owed to staked liquidity, then calculates fee levied on unstaked liquidity
  /// @param feeAmount Total fees
  /// @param _liquidity Current liquidity in active tick
  /// @param _stakedLiquidity Current staked liquidity in active tick
  /// @return unstakedFeeAmount Fee amount for unstaked LPs after accounting for staked liquidity contribution and unstaked fee
  /// @return stakedFeeAmount Fee amount for staked LPs consisting of staked liquidity contribution and unstaked fee
  function splitFees(
    uint256 feeAmount,
    uint128 _liquidity,
    uint128 _stakedLiquidity
  ) internal view returns (uint256 unstakedFeeAmount, uint256 stakedFeeAmount) {
    stakedFeeAmount = FullMath.mulDivRoundingUp(feeAmount, _stakedLiquidity, _liquidity);
    (unstakedFeeAmount, stakedFeeAmount) = applyUnstakedFees(feeAmount - stakedFeeAmount, stakedFeeAmount);
  }

  /// @notice Calculates fee for levied on unstaked liquidity only
  /// @param _unstakedFeeAmount Fee amount for unstaked LPs net of staked liquidity contribution
  /// @param _stakedFeeAmount Fee amount for staked LPs consisting of staked liquidity contribution
  /// @return unstakedFeeAmount Fee amount for unstaked LPs after accounting for staked liquidity contribution and unstaked fee
  /// @return stakedFeeAmount Fee amount for staked LPs consisting of staked liquidity contribution and unstaked fee
  function applyUnstakedFees(
    uint256 _unstakedFeeAmount,
    uint256 _stakedFeeAmount
  ) internal view returns (uint256 unstakedFeeAmount, uint256 stakedFeeAmount) {
    uint256 _stakedFee = FullMath.mulDivRoundingUp(_unstakedFeeAmount, unstakedFee(), 1_000_000);
    unstakedFeeAmount = _unstakedFeeAmount - _stakedFee;
    stakedFeeAmount = _stakedFeeAmount + _stakedFee;
  }

  // calculates the fee growths for unstaked liquidity and returns it with the staked fee amount
  function calculateFees(
    uint256 feeAmount,
    uint128 _liquidity,
    uint128 _stakedLiquidity
  ) internal view returns (uint256 feeGrowthGlobalX128, uint256 stakedFeeAmount) {
    // if there is only staked liquidity
    if (_liquidity == _stakedLiquidity) {
      stakedFeeAmount = feeAmount;
    }
    // if there is only unstaked liquidity
    else if (_stakedLiquidity == 0) {
      (uint256 unstakedFeeAmount, uint256 _stakedFeeAmount) = applyUnstakedFees(feeAmount, 0);
      feeGrowthGlobalX128 = FullMath.mulDiv(unstakedFeeAmount, FixedPoint128.Q128, _liquidity);
      stakedFeeAmount = _stakedFeeAmount;
    }
    // if there are staked and unstaked liquidities
    else {
      (uint256 unstakedFeeAmount, uint256 _stakedFeeAmount) = splitFees(feeAmount, _liquidity, _stakedLiquidity);
      feeGrowthGlobalX128 = FullMath.mulDiv(unstakedFeeAmount, FixedPoint128.Q128, _liquidity - _stakedLiquidity);
      stakedFeeAmount = _stakedFeeAmount;
    }
  }

  /// @inheritdoc ICLPoolOwnerActions
  function collectFees(address recipient) external override returns (uint128 amount0, uint128 amount1) {
    _lock();
    _onlyGauge();
    (amount0, amount1) = CL.collectFees(gaugeFees, recipient, token0, token1);
    _unlock();
  }

  /// @inheritdoc ICLPoolActions
  function setGaugeAndPositionManager(address _gauge, address _nft) external override {
    _lock();
    CL.validateGaugeFactory(factoryRegistry, factory);
    require(gauge == address(0));
    gauge = _gauge;
    nft = _nft;
    // Pull any emissions the voter accrued before the gauge was connected. No liquidity can be
    // staked yet, so the accrual banks into rollover instead of crediting future stakers, and the
    // gauge's settlement cursor is initialized in the same call.
    uint256 _rewardsToDistribute = ICLGauge(_gauge).settleGauge();
    _updateRewardsGrowthGlobal(_rewardsToDistribute, uint48(block.timestamp), lastUpdated);
    _unlock();
  }
}
"},"contracts/core/interfaces/IFactoryRegistry.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity >=0.7.6;

/**
 * @title IFactoryRegistry
 * @notice Surface of the metadex `FactoryRegistry` the CL stack calls.
 * @dev A pool is a "target" and a pool factory a "target factory". The periphery keeps its own read-only mirror in
 *      `contracts/periphery/interfaces/IV3FactoryRegistry.sol` for the quoters.
 */
interface IFactoryRegistry {
  /**
   * @notice Registers a gauge factory and the target factory it serves as a pair, writing their permanent link.
   * @param gaugeFactory The gauge factory to register.
   * @param targetFactory The target (pool) factory the gauge factory serves.
   */
  function registerFactories(address gaugeFactory, address targetFactory) external;

  /**
   * @notice Records a freshly deployed target. Called by the target factory inside its own creation function.
   * @param target The deployed target (pool).
   */
  function registerTarget(address target) external;

  /**
   * @notice True when a target (pool) factory is in the approval set.
   * @param targetFactory The target factory to check.
   * @return Whether the factory is approved.
   */
  function isTargetFactoryApproved(address targetFactory) external view returns (bool);

  /**
   * @notice The gauge factory serving a target factory.
   * @param targetFactory The target factory to resolve.
   * @return The linked gauge factory, zero for an unlinked factory.
   */
  function targetFactoryToGaugeFactory(address targetFactory) external view returns (address);

  /**
   * @notice The gauge over a target (pool).
   * @param target The target to resolve.
   * @return The gauge for `target`, zero when none is recorded.
   */
  function targetToGauge(address target) external view returns (address);

  /**
   * @notice Effective emission cap for a gauge, resolved through the factory that deployed it.
   * @dev Returns zero when the gauge is unknown or the factory call reverts.
   * @param gauge The gauge to resolve.
   * @return The effective cap in tokens per second.
   */
  function emissionCap(address gauge) external view returns (uint128);
}
"},"contracts/core/libraries/Position.sol":{"content":"// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0 <0.8.0;

import './FixedPoint128.sol';
import './FullMath.sol';
import './LiquidityMath.sol';

/// @title Position
/// @notice Positions represent an owner address' liquidity between a lower and upper tick boundary
/// @dev Positions store additional state for tracking fees owed to the position
library Position {
  // info stored for each user's position
  struct Info {
    // the amount of liquidity owned by this position
    uint128 liquidity;
    // fee growth per unit of liquidity as of the last update to liquidity or fees owed
    uint256 feeGrowthInside0LastX128;
    uint256 feeGrowthInside1LastX128;
    // the fees owed to the position owner in token0/token1
    uint128 tokensOwed0;
    uint128 tokensOwed1;
  }

  /// @notice Returns the Info struct of a position, given an owner and position boundaries
  /// @param self The mapping containing all user positions
  /// @param owner The address of the position owner
  /// @param tickLower The lower tick boundary of the position
  /// @param tickUpper The upper tick boundary of the position
  /// @return position The position info struct of the given owners' position
  function get(
    mapping(bytes32 => Info) storage self,
    address owner,
    int24 tickLower,
    int24 tickUpper
  ) internal view returns (Position.Info storage position) {
    position = self[keccak256(abi.encodePacked(owner, tickLower, tickUpper))];
  }

  /// @notice Credits accumulated fees to a user's position
  /// @param self The individual position to update
  /// @param liquidityDelta The change in pool liquidity as a result of the position update
  /// @param feeGrowthInside0X128 The all-time fee growth in token0, per unit of liquidity, inside the position's tick boundaries
  /// @param feeGrowthInside1X128 The all-time fee growth in token1, per unit of liquidity, inside the position's tick boundaries
  /// @param staked Signifies if the position is staked in the gauge or not
  function update(
    Info storage self,
    int128 liquidityDelta,
    uint256 feeGrowthInside0X128,
    uint256 feeGrowthInside1X128,
    bool staked
  ) internal {
    Info memory _self = self;

    uint128 liquidityNext;
    if (liquidityDelta == 0) {
      require(_self.liquidity > 0, 'NP'); // disallow pokes for 0 liquidity positions
      liquidityNext = _self.liquidity;
    } else {
      liquidityNext = LiquidityMath.addDelta(_self.liquidity, liquidityDelta);
    }

    uint128 tokensOwed0;
    uint128 tokensOwed1;
    if (!staked) {
      // calculate accumulated fees
      tokensOwed0 = uint128(
        FullMath.mulDiv(feeGrowthInside0X128 - _self.feeGrowthInside0LastX128, _self.liquidity, FixedPoint128.Q128)
      );
      tokensOwed1 = uint128(
        FullMath.mulDiv(feeGrowthInside1X128 - _self.feeGrowthInside1LastX128, _self.liquidity, FixedPoint128.Q128)
      );
    }

    // update the position
    if (liquidityDelta != 0) self.liquidity = liquidityNext;
    self.feeGrowthInside0LastX128 = feeGrowthInside0X128;
    self.feeGrowthInside1LastX128 = feeGrowthInside1X128;
    if (tokensOwed0 > 0 || tokensOwed1 > 0) {
      // overflow is acceptable, have to withdraw before you hit type(uint128).max fees
      self.tokensOwed0 += tokensOwed0;
      self.tokensOwed1 += tokensOwed1;
    }
  }
}
